window.__CH("c2",["<div class=\"hw jl\">遅い</div><div class=\"def\">(時間が)serus;(速度や動作が)tardus, lentus.</div><div class=\"def\">▼<b>遅く</b>(時間が)sero;(=ゆっくり, のろのろと)tarde, lente.</div><div class=\"def\">▼<b>夜遅く</b> pervesperi.</div><div class=\"def\">▼<b>～こと</b> tarditas.</div><div class=\"def\">▼<b>遅くなる</b>(=のろくなる)tardesco.</div><div class=\"def\">⇒<a href=\"entry://遅れ\">遅れ</a>,<a href=\"entry://遅れる\">遅れる</a>.</div>\r\n","<div class=\"hw jl\">遅れ</div><div class=\"def\">(=遅延)mora, commoratio.</div>\r\n","<div class=\"hw jl\">遅れる</div><div class=\"def\">se tardare(← tardo), moror(<i>dep</i>), commoror(<i>dep</i>).</div><div class=\"def\">▼<b>遅れて</b> sero.</div><div class=\"ex2\">遅れて来る<span class=\"ext\">serius venio.</span></div><div class=\"ex2\">少し遅れて<span class=\"ext\">paulo serius.</span></div><div class=\"ex2\">かなり遅れて<span class=\"ext\">serius aliquanto.</span></div><div class=\"ex2\">遅れずに(=すぐに)<span class=\"ext\">sine mora.</span></div><div class=\"ex2\">私の時計はよく遅れます<span class=\"ext\">meum horologium solet retardari.</span></div>\r\n","<div class=\"hw jl\">遅刻</div><div class=\"def\">▼<b>～する</b> non in tempore adsum;(...に)〈ad alqd〉 serius venio.</div><div class=\"def\">⇒<a href=\"entry://間に合う\">間に合う</a>.</div>\r\n","<div class=\"hw jl\">遊び</div><div class=\"def\">(=遊戯, 気晴らし)ludus, lusio.</div>\r\n","<div class=\"hw jl\">遊ぶ</div><div class=\"def\">ludo, illudo.</div><div class=\"def\">▼<b>～人</b> lusor.</div><div class=\"def\">▼(...をして)<b>～</b>(=楽しむ)(alqd)facio delectationis causā.</div>\r\n","<div class=\"hw jl\">遊園地</div><div class=\"def\">horti publici oblectatorii(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">運</div><div class=\"def\">fortuna, fors.</div><div class=\"def\">▼<b>幸～</b> secunda fortuna.</div><div class=\"def\">▼<b>悲～</b> adversa fortuna.</div><div class=\"def\">⇒<a href=\"entry://運命\">運命</a>.</div>\r\n","<div class=\"hw jl\">運ぶ</div><div class=\"def\">fero, porto, gero;(担いで)bajulo;(ある場所から別の場所へ)transporto, transfero, transmoveo.</div><div class=\"def\">▼<b>運んでくる</b> apporto, aggero.</div><div class=\"def\">▼<b>運び出す</b> effero, egero.</div>\r\n","<div class=\"hw jl\">運動</div><div class=\"def\">(物体の)motus, motio;(=体育)corporis exercitatio;(=体操)palaestrica ars;(=社会的な変革)mutatio.</div><div class=\"def\">▼<b>～競技</b> certamen athleticum.</div><div class=\"def\">▼<b>芸術～</b> artium mutatio.</div>\r\n","<div class=\"hw jl\">運命</div><div class=\"def\">fatum, sors, fortuna.</div><div class=\"def\">▼<b>～の女神</b> Fortuna.</div><div class=\"def\">⇒<a href=\"entry://運\">運</a>,<a href=\"entry://偶然\">偶然</a>,<a href=\"entry://幸運\">幸運</a>.</div>\r\n","<div class=\"hw jl\">運搬</div><div class=\"def\">subvectio.</div><div class=\"def\">▼<b>～する</b> subveho, subvecto.</div>\r\n","<div class=\"hw jl\">運河</div><div class=\"def\">canalis, fossa.</div>\r\n","<div class=\"hw jl\">運賃</div><div class=\"def\">vectura.</div>\r\n","<div class=\"hw jl\">運転</div><div class=\"def\">▼(自動車を)<b>～する</b> vehiculum automatarium duco.</div><div class=\"def\">▼<b>～免許</b> diploma vehiculo automatario ducendo.</div>\r\n","<div class=\"hw jl\">運転手</div><div class=\"def\">(自動車の)autocinetistes, autoraedarius, autocineti ductor.</div><div class=\"def\">▼<b>タクシー～</b> autocineti meritorii rector.</div>\r\n","<div class=\"hw jl\">運送</div><div class=\"def\">subvectio.</div><div class=\"def\">⇒<a href=\"entry://運搬\">運搬</a>.</div>\r\n","<div class=\"hw jl\">過ぎる</div><div class=\"def\">▼(...)過ぎて(=あまりに...で)nimium, nimis.</div><div class=\"def\">⇒<a href=\"entry://過ぎ去る\">過ぎ去る</a>,<a href=\"entry://あまり\">あまり</a>.</div>\r\n","<div class=\"hw jl\">過ぎ去る</div><div class=\"def\">(時間が)praetereo, praelabor(<i>dep</i>).</div><div class=\"def\">▼<b>過ぎ去った</b> praeteritus.</div><div class=\"ex2\">過ぎ去った年月<span class=\"ext\">praeterita aetas.</span></div>\r\n","<div class=\"hw jl\">過ごす</div><div class=\"def\">dego, transigo.</div><div class=\"ex2\">煩いなく一生を～<span class=\"ext\">omne tempus aetatis sine molestia dego.</span></div><div class=\"ex2\">無為に日を～<span class=\"ext\">per otium transigo.</span></div>\r\n","<div class=\"hw jl\">過ち</div><div class=\"def\">(=過失)error, erratum, vitium;(倫理的な)(=罪)culpa, vitium, peccatum.</div><div class=\"ex2\">多くの～を犯す<span class=\"ext\">multa pecco.</span></div><div class=\"def\">⇒<a href=\"entry://間違い\">間違い</a>.</div>\r\n","<div class=\"hw jl\">過剰</div><div class=\"def\">(=過多)(magna)abundantia, superabundantia, nimietas, nimium.</div><div class=\"def\">▼<b>～な</b> nimius, superabundans.</div><div class=\"def\">▼<b>～に</b> nimis, superabundanter, nimium.</div><div class=\"def\">▼(...が)<b>～である</b> 〈+<i>gen</i>〉 est nimium, superabundo.</div><div class=\"def\">⇒<a href=\"entry://過度\">過度</a>.</div>\r\n","<div class=\"hw jl\">過労死</div><div class=\"def\">mors propter nimium laborem.</div><div class=\"def\">▼<b>～する</b> morior(<i>dep</i>)propter nimium laborem.</div>\r\n","<div class=\"hw jl\">過半数</div><div class=\"def\">major pars, maxima pars.</div><div class=\"def\">⇒<a href=\"entry://大半\">大半</a>.</div>\r\n","<div class=\"hw jl\">過去</div><div class=\"def\">(tempus)praeteritum.</div><div class=\"def\">▼<b>～の</b> praeteritus.</div><div class=\"def\">⇒<a href=\"entry://昔\">昔</a>.</div>\r\n","<div class=\"hw jl\">過失</div><div class=\"def\">culpa, delictum, peccatum, vitium, error.</div><div class=\"ex2\">～を犯す<span class=\"ext\">culpam committo.</span></div>\r\n","<div class=\"hw jl\">過度</div><div class=\"def\">nimium, intemperantia, immodestia, intemperies.</div><div class=\"def\">▼<b>～の</b> nimius, intemperans, intemperatus, immodestus, immoderatus.</div><div class=\"def\">▼<b>～に</b> extra modum, nimis, nimium, intemperanter, immodice.</div>\r\n","<div class=\"hw jl\">過激</div><div class=\"def\">▼<b>～な</b>(=行動や考えが極端な)extremus, immoderatus, immodicus.</div><div class=\"ex2\">過激派グループ<span class=\"ext\">grex extremistarum.</span></div>\r\n","<div class=\"hw jl\">過酷</div><div class=\"def\">▼<b>～な</b> durissimus(← durus), asperrimus(← asper), amarissimus(← amarus), acerbissimus(← acerbus);(=冷酷な, 残忍な, 無慈悲な)saevus, crudelis, acer, ferus, inhumanus.</div>\r\n","<div class=\"hw jl\">道</div><div class=\"def\">iter, via;(=小道)semita, trames.</div><div class=\"def\">▼<b>～案内</b>(人)itineris ductor.</div>\r\n","<div class=\"hw jl\">道具</div><div class=\"def\">organum, instrumentum;(鉄製の)ferramentum.</div><div class=\"def\">⇒<a href=\"entry://装置\">装置</a>.</div>\r\n","<div class=\"hw jl\">道徳</div><div class=\"def\">moralia(<i>pl</i>).</div><div class=\"def\">▼<b>～的な</b> moralis.</div><div class=\"def\">▼<b>～的に</b> moraliter.</div><div class=\"def\">⇒<a href=\"entry://倫理\">倫理</a>,<a href=\"entry://習慣\">習慣</a>.</div>\r\n","<div class=\"hw jl\">道理</div><div class=\"def\">ratio.</div><div class=\"def\">▼<b>～をわきまえた</b> sanus.</div><div class=\"def\">▼<b>～を欠いた</b>(=不条理な)insanus, rationis expers.</div><div class=\"def\">⇒<a href=\"entry://分別\">分別</a>,<a href=\"entry://理性\">理性</a>.</div>\r\n","<div class=\"hw jl\">道路</div><div class=\"def\">via, iter.</div>\r\n","<div class=\"hw jl\">道連れ</div><div class=\"def\">comes, convector.</div><div class=\"ex2\">死の～<span class=\"ext\">comes mortis.</span></div>\r\n","<div class=\"hw jl\">達する</div><div class=\"def\">attingo, assequor(<i>dep</i>), adipiscor(<i>dep</i>), consequor(<i>dep</i>), pervenio.</div><div class=\"def\">⇒<a href=\"entry://着く\">着く</a>.</div>\r\n","<div class=\"hw jl\">達成</div><div class=\"def\">exitus, effectus.</div><div class=\"def\">▼<b>～する</b> perficio, consequor(<i>dep</i>), ad effectum(alcis rei)pervenio.</div><div class=\"def\">⇒<a href=\"entry://完成\">完成</a>,<a href=\"entry://実現\">実現</a>.</div>\r\n","<div class=\"hw jl\">違う</div><div class=\"def\"><span class=\"pos3\">[形]</span>(=違った)dissimilis, dispar, diversus, alius.</div><div class=\"def\">━<span class=\"pos3\">[動]</span>(=違っている)differo, disto, discrepo, dissideo, distat(<i>impers</i>).</div><div class=\"def\">━<span class=\"pos3\">[副]</span>(=いいえ, 真実と違う)non, minime vero.</div><div class=\"def\">▼<b>違ったやり方で</b> aliter.</div><div class=\"def\">▼<b>違い</b> differentia.</div><div class=\"def\">⇒<a href=\"entry://異なる\">異なる</a>,<a href=\"entry://差異\">差異</a>.</div>\r\n","<div class=\"hw jl\">違反</div><div class=\"def\">noxia, violatio, delictum.</div><div class=\"def\">▼<b>～する</b> delinquo, delictum committo;(=法に反して行なう)contra legem facio [committo].</div><div class=\"def\">▼<b>～者</b> ruptor, violator.</div><div class=\"def\">⇒<a href=\"entry://罪\">罪</a>.</div>\r\n","<div class=\"hw jl\">違法</div><div class=\"def\">quod contra legem factum.</div><div class=\"def\">▼<b>～な</b> contra legem factus, illicitus.</div><div class=\"def\">▼<b>～に</b> contra legem, illicite.</div><div class=\"def\">⇒<a href=\"entry://犯罪\">犯罪</a>.</div>\r\n","<div class=\"hw jl\">遠い</div><div class=\"def\"><span class=\"pos3\">[形]</span>(=遠く離れた)remotus, semotus, longus, longinquus.</div><div class=\"def\">━<span class=\"pos3\">[動]</span>(=遠く離れている)(...から)〈a re〉 longe absum, procul sum.</div><div class=\"ex2\">祖国から遠く離れて<span class=\"ext\">patriā procul.</span></div>\r\n","<div class=\"hw jl\">遠ざける</div><div class=\"def\">amoveo, removeo, semoveo, alieno, abdo.</div><div class=\"def\">⇒<a href=\"entry://防ぐ\">防ぐ</a>.</div>\r\n","<div class=\"hw jl\">遠出</div><div class=\"def\">excursio.</div><div class=\"def\">▼<b>～する</b> excurro.</div><div class=\"def\">⇒<a href=\"entry://遠征\">遠征</a>.</div>\r\n","<div class=\"hw jl\">遠回し</div><div class=\"def\">circuitio, circuitus.</div><div class=\"def\">▼<b>～の</b>(=婉曲の)obliquus.</div><div class=\"def\">▼<b>～に</b> oblique.</div>\r\n","<div class=\"hw jl\">遠回り</div><div class=\"def\">⇒<a href=\"entry://回り道\">回り道</a>.</div>\r\n","<div class=\"hw jl\">遠征</div><div class=\"def\">expeditio, excursio.</div><div class=\"ex2\">～を企てる<span class=\"ext\">expeditionem suscipio.</span></div>\r\n","<div class=\"hw jl\">遠慮</div><div class=\"def\">modestia, verecundia.</div><div class=\"def\">▼<b>～して</b> verecunde.</div><div class=\"def\">⇒<a href=\"entry://謙虚\">謙虚</a>,<a href=\"entry://控えめ\">控えめ</a>,<a href=\"entry://自制\">自制</a>.</div>\r\n","<div class=\"hw jl\">遠足</div><div class=\"def\">excursio.</div><div class=\"def\">▼<b>～する</b> excurro.</div>\r\n","<div class=\"hw jl\">遡る</div><div class=\"def\">(川を)flumine averso subvehor(<i>pass</i>), adversum flumen subeo, adversas aquas subeo.</div>\r\n","<div class=\"hw jl\">適した</div><div class=\"def\">idoneus.</div>\r\n","<div class=\"hw jl\">適切</div><div class=\"def\">▼<b>～な</b> appositus, aptus, idoneus, conveniens, idoneus.</div><div class=\"def\">▼<b>～に</b> apte.</div><div class=\"def\">⇒<a href=\"entry://適当\">適当</a>,<a href=\"entry://ふさわしい\">ふさわしい</a>.</div>\r\n","<div class=\"hw jl\">適合</div><div class=\"def\">▼<b>～(性)</b> accommodatio.</div><div class=\"def\">▼<b>～した</b> accommodatus.</div>\r\n","<div class=\"hw jl\">適度</div><div class=\"def\">moderatio, temperatura.</div><div class=\"def\">▼<b>～な</b> temperatus, temperans.</div><div class=\"def\">▼<b>～に</b> temperate.</div>\r\n","<div class=\"hw jl\">適当</div><div class=\"def\">▼<b>～な</b> aptus, congruens, conveniens, opportunus.</div><div class=\"def\">⇒<a href=\"entry://適切\">適切</a>.</div>\r\n","<div class=\"hw jl\">適応</div><div class=\"def\">accommodatio.</div><div class=\"def\">▼<b>～する</b> accommodor(<i>pass</i>), aptor(<i>pass</i>).</div><div class=\"def\">▼<b>～させる</b> accommodo, apto.</div>\r\n","<div class=\"hw jl\">選ぶ</div><div class=\"def\">eligo, deligo, creo.</div><div class=\"def\">▼<b>～こと</b> electio, delectio.</div><div class=\"def\">▼<b>選ばれた</b>(=えり抜きの)electus, delectus.</div><div class=\"ex2\">確実なものより不確実なものを～<span class=\"ext\">incerta pro certis malo.</span></div>\r\n","<div class=\"hw jl\">選手</div><div class=\"def\">athleta.</div><div class=\"def\">⇒<a href=\"entry://競技\">競技</a>.</div>\r\n","<div class=\"hw jl\">選択</div><div class=\"def\">delectus, electio.</div><div class=\"def\">▼<b>～する</b> eligo.</div><div class=\"def\">⇒<a href=\"entry://選ぶ\">選ぶ</a>.</div>\r\n","<div class=\"hw jl\">選挙</div><div class=\"def\">creatio, suffragium, comitium.</div><div class=\"def\">▼<b>～人</b> suffragator.</div><div class=\"def\">▼<b>～権</b> jus impertiendi suffragii.</div><div class=\"def\">⇒<a href=\"entry://投票\">投票</a>.</div>\r\n","<div class=\"hw jl\">遺伝</div><div class=\"def\">hereditas.</div><div class=\"def\">▼<b>～の</b> hereditarius.</div><div class=\"def\">▼(病気などが親から子に)<b> ～する</b> per successiones traditur(<i>pass</i>).</div><div class=\"def\">▼<b>～子</b> gen, genum.</div>\r\n","<div class=\"hw jl\">遺族</div><div class=\"def\">(=死者の家族)hominis mortui familia(死者が男の場合), feminae mortuae familia(死者が女の場合).</div>\r\n","<div class=\"hw jl\">遺書</div><div class=\"def\">⇒<a href=\"entry://遺言\">遺言</a>.</div>\r\n","<div class=\"hw jl\">遺産</div><div class=\"def\">hereditas, heredium, legatum.</div><div class=\"def\">▼<b>～に関する</b> hereditarius.</div><div class=\"ex2\">(人が)～を相続する<span class=\"ext\">legatum 〈alci〉 obvenit.</span></div><div class=\"ex2\">～を手に入れる<span class=\"ext\">hereditatem accipio.</span></div><div class=\"def\">⇒<a href=\"entry://相続\">相続</a>.</div>\r\n","<div class=\"hw jl\">遺言</div><div class=\"def\">▼<b>～(状)</b> testamentum.</div><div class=\"def\">▼<b>～に関する</b> testamentarius.</div><div class=\"def\">▼<b>～(状)をこしらえる</b> testamentum facio [conscribo], testor(<i>dep</i>).</div><div class=\"def\">▼<b>～をせずに死ぬ</b> intestato morior(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">遺跡</div><div class=\"def\">(=廃虚)ruinae(<i>pl</i>), vestigia(<i>pl</i>).</div><div class=\"def\">▼<b>考古学～</b> situs archeologicus.</div>\r\n","<div class=\"hw jl\">避ける</div><div class=\"def\">vito, evito, devito, refugio.</div><div class=\"def\">▼<b>避けられる</b> evitabilis.</div><div class=\"def\">▼<b>避けられない</b> inevitabilis.</div>\r\n","<div class=\"hw jl\">避妊</div><div class=\"def\">conceptus impeditio.</div><div class=\"def\">▼<b>～法</b> methodi contra conceptionem(<i>pl</i>), atocia.</div><div class=\"def\">▼<b>～薬</b> atocium.</div>\r\n","<div class=\"hw jl\">避難</div><div class=\"def\">refugium.</div><div class=\"def\">▼<b>～する</b> confugio, perfugio, refugio, suffugio.</div><div class=\"def\">▼<b>～所</b> perfugium, confugium, refugium, suffugium, tectum, asylum.</div><div class=\"def\">⇒<a href=\"entry://避ける\">避ける</a>.</div>\r\n","<div class=\"hw jl\">邪魔</div><div class=\"def\">prohibitio, impedimentum.</div><div class=\"def\">▼<b>～された</b> impeditus.</div><div class=\"def\">▼<b>～する</b> prohibeo, impedio, obsto, obsisto, officio, intermitto.</div><div class=\"def\">▼<b>～になる</b> obsum.</div><div class=\"def\">⇒<a href=\"entry://障害\">障害</a>.</div>\r\n","<div class=\"hw jl\">郊外</div><div class=\"def\">suburbium, suburbanitas.</div><div class=\"def\">▼<b>～の</b> suburbanus.</div>\r\n","<div class=\"hw jl\">部</div><div class=\"def\">(=一部, 部分)pars;(=体の部位)regio;(=区分)sectio, divisio.</div>\r\n","<div class=\"hw jl\">部下</div><div class=\"def\">subjectus(<i>m</i>).</div><div class=\"ex2\">～の者に対して非常に乱暴な独裁者<span class=\"ext\">tyrannus violentissimus in suos.</span></div>\r\n","<div class=\"hw jl\">部分</div><div class=\"def\">pars, portio;(小さな)particulum, portiuncula(<i>pl</i>).</div><div class=\"def\">▼<b>～的に</b> partim, in [ex] parte.</div><div class=\"def\">▼<b>～に分ける</b> partior(<i>dep</i>).</div><div class=\"ex2\">ガリア全体は三つの～に分かれている<span class=\"ext\">Gallia est omnis divisa in partes tres.</span></div>\r\n","<div class=\"hw jl\">部品</div><div class=\"def\">membrum, pars.</div>\r\n","<div class=\"hw jl\">部屋</div><div class=\"def\">membrum.</div><div class=\"def\">⇒<a href=\"entry://寝室\">寝室</a>,<a href=\"entry://居間\">居間</a>,<a href=\"entry://応接間\">応接間</a>.</div>\r\n","<div class=\"hw jl\">部署</div><div class=\"def\">statio, locus.</div><div class=\"def\">▼<b>～につかせる</b> statuo, pono.</div>\r\n","<div class=\"hw jl\">郵便</div><div class=\"def\">publicus cursus.</div><div class=\"def\">▼<b>～局</b> aedes cursuales(<i>pl</i>).</div><div class=\"def\">▼<b>～局員</b> rei cursuali praepositus [addictus](<i>m</i>).</div><div class=\"def\">▼<b>～葉書</b> chartula cursoria [cursualis].</div><div class=\"def\">▼<b>～配達人</b> tabellarius.</div><div class=\"def\">▼<b>～番号</b> codex cursualis.</div><div class=\"def\">▼<b>～の</b> cursualis.</div><div class=\"def\">⇒<a href=\"entry://ポスト\">ポスト</a>,<a href=\"entry://切手\">切手</a>,<a href=\"entry://葉書\">葉書</a>,<a href=\"entry://為替\">為替</a>.</div>\r\n","<div class=\"hw jl\">郵送</div><div class=\"def\">missio per cursum publicum.</div><div class=\"def\">▼<b>～する</b> mitto per cursum publicum.</div><div class=\"def\">⇒<a href=\"entry://郵便\">郵便</a>.</div>\r\n","<div class=\"hw jl\">郷土</div><div class=\"def\">⇒<a href=\"entry://故郷\">故郷</a>,<a href=\"entry://祖国\">祖国</a>.</div>\r\n","<div class=\"hw jl\">都会</div><div class=\"def\">urbs.</div><div class=\"def\">▼<b>～らしさ, ～風</b> urbanitas.</div><div class=\"def\">▼<b>～(人)の, ～風の</b> urbanus.</div>\r\n","<div class=\"hw jl\">都合</div><div class=\"def\">commodum.</div><div class=\"ex2\">私の～で<span class=\"ext\">meo commodo.</span></div><div class=\"ex2\">あなたの～がよければ<span class=\"ext\">cum erit tuum commodum.</span></div><div class=\"def\">⇒<a href=\"entry://好都合\">好都合</a>,<a href=\"entry://好ましい\">好ましい</a>.</div>\r\n","<div class=\"hw jl\">都市</div><div class=\"def\">civitas, urbs, oppidum;(国家としての)civitas.</div><div class=\"def\">▼<b>～の</b>(=都会の)urbanus.</div><div class=\"def\">⇒<a href=\"entry://町・街\">町</a>.</div>\r\n","<div class=\"hw jl\">配る</div><div class=\"def\">distribuo.</div><div class=\"def\">⇒<a href=\"entry://分配\">分配</a>.</div>\r\n","<div class=\"hw jl\">配当</div><div class=\"def\">lucri portio.</div>\r\n","<div class=\"hw jl\">配給</div><div class=\"def\">distributio.</div><div class=\"def\">▼<b>～する</b> distribuo.</div><div class=\"def\">⇒<a href=\"entry://分配\">分配</a>,<a href=\"entry://供給\">供給</a>.</div>\r\n","<div class=\"hw jl\">配置</div><div class=\"def\">dispositio.</div><div class=\"def\">▼<b>～する</b> dispono, como.</div>\r\n","<div class=\"hw jl\">配達</div><div class=\"def\">traditio.</div><div class=\"def\">▼<b>～する</b> trado.</div><div class=\"def\">▼(手紙の)<b> ～人</b> tabellarius.</div>\r\n","<div class=\"hw jl\">酒</div><div class=\"def\">(=ぶどう酒)vinum.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">食前酒<span class=\"ext\">potio aperitiva, propoma.</span></div><div class=\"cf\">カクテル<span class=\"ext\">mixtura.</span></div><div class=\"cf\">シャンパン(シャンパーニュ)<span class=\"ext\">vinum ex Campania Gallica.</span></div><div class=\"cf\">ビール<span class=\"ext\">cervesia, cerevisia, zythum.</span></div><div class=\"def\">⇒<a href=\"entry://アルコール\">アルコール</a>.</div>\r\n","<div class=\"hw jl\">酔う</div><div class=\"def\">▼<b>酒に～</b> vino inebrior(<i>pass</i>);(=泥酔する)se vino obruere(← obruo).</div><div class=\"def\">▼<b>酔わす</b> ebrium [temulentum] facio.</div><div class=\"def\">▼<b>酔った</b> ebrius, temulentus, vinolentus, vinosus.</div><div class=\"def\">▼<b>酔った状態</b> ebrietas, temulentia, vinolentia.</div>\r\n","<div class=\"hw jl\">酔っ払い</div><div class=\"def\">ebriosus(<i>m</i>).</div><div class=\"def\">⇒<a href=\"entry://酔う\">酔う</a>.</div>\r\n","<div class=\"hw jl\">酢</div><div class=\"def\">acetum.</div>\r\n","<div class=\"hw jl\">酵母</div><div class=\"def\">fermentum.</div><div class=\"def\">⇒<a href=\"entry://発酵\">発酵</a>.</div>\r\n","<div class=\"hw jl\">酵素</div><div class=\"def\">enzyma, solubile fermentum.</div><div class=\"def\">▼<b>～の</b> enzymaticus, fermentacius.</div>\r\n","<div class=\"hw jl\">酸</div><div class=\"def\">acidum.</div>\r\n","<div class=\"hw jl\">酸っぱい</div><div class=\"def\">acidus, acerbus, immitis.</div><div class=\"def\">▼<b>酸っぱくなる</b> acesco.</div><div class=\"ex2\">～ぶどう酒<span class=\"ext\">acerbum.</span></div><div class=\"def\">⇒<a href=\"entry://酸\">酸</a>.</div>\r\n","<div class=\"hw jl\">酸味</div><div class=\"def\">acerbitas, acor.</div>\r\n","<div class=\"hw jl\">醜い</div><div class=\"def\">turpis, deformis, foedus, taeter.</div><div class=\"def\">▼<b>醜さ</b> turpitudo, deformitas, foeditas.</div>\r\n","<div class=\"hw jl\">重い</div><div class=\"def\">(=重量が大きい)gravis, ponderosus;(病気が)gravis, periculosus;(罪や罰が)magnus.</div><div class=\"def\">▼<b>重さ</b> gravitas, pondus.</div>\r\n","<div class=\"hw jl\">重さ</div><div class=\"def\">⇒<a href=\"entry://重い\">重い</a>.</div>\r\n","<div class=\"hw jl\">重なる</div><div class=\"def\">(=ある物の上にある物が乗る)superponor(<i>pass</i>).</div><div class=\"ex2\">災いに災いが～(=続けざまに生じる)<span class=\"ext\">damna damnis continuantur.</span></div>\r\n","<div class=\"hw jl\">重ねる</div><div class=\"def\">superpono;(=積み重ねる)cumulo, accumulo, acervo, aggero.</div><div class=\"ex2\">罪に罪を～<span class=\"ext\">scelere scelus cumulo.</span></div><div class=\"ex2\">殺人に殺人を～<span class=\"ext\">caede caedem accumulo.</span></div>\r\n","<div class=\"hw jl\">重大</div><div class=\"def\">gravitas.</div><div class=\"def\">▼<b>～な</b> gravis, magnus.</div><div class=\"ex2\">そのことがおまえにとってどれほど～か?<span class=\"ext\">quid tua id refert?</span></div>\r\n","<div class=\"hw jl\">重苦しい</div><div class=\"def\">gravis.</div>\r\n","<div class=\"hw jl\">重荷</div><div class=\"def\">onus, sarcina, pondus.</div><div class=\"ex2\">～から解放する<span class=\"ext\">exonero.</span></div>\r\n","<div class=\"hw jl\">重要</div><div class=\"def\">▼<b>～(性)</b> gravitas, momentum, magnitudo.</div><div class=\"def\">▼(...が)<b>～だ</b> 〈+<i>inf</i>〉 refert(<i>impers</i>), interest(<i>impers</i>), magnum momentum habet(← habeo), magni momenti est(← sum).</div><div class=\"def\">▼<b>～でない</b> parvi momenti est(← sum).</div><div class=\"def\">▼<b>～な</b> gravis, magni momenti.</div><div class=\"def\">⇒<a href=\"entry://重大\">重大</a>.</div>\r\n","<div class=\"hw jl\">野党</div><div class=\"def\">adversa factio.</div><div class=\"def\">⇒<a href=\"entry://与党\">与党</a>.</div>\r\n","<div class=\"hw jl\">野原</div><div class=\"def\">campus, ager, apertum, campania(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://牧草地\">牧草地</a>.</div>\r\n","<div class=\"hw jl\">野外</div><div class=\"def\">▼<b>～で</b> sub divo, in propatulo, in aere.</div>\r\n","<div class=\"hw jl\">野心</div><div class=\"def\">ambitio(gloriae), ambitus, honorum cupiditas, laudis studium;(権力や支配への)(dominandi [imperandi, regni])cupiditas.</div><div class=\"def\">▼<b>～家の</b> ambitiosus, gloriae cupidus [appetens], honoris avidus.</div>\r\n","<div class=\"hw jl\">野獣</div><div class=\"def\">fera.</div><div class=\"def\">▼<b>～の</b> ferinus.</div><div class=\"def\">⇒<a href=\"entry://野生\">野生</a>.</div>\r\n","<div class=\"hw jl\">野生</div><div class=\"def\">▼<b>～の</b>(=馴らされていない)ferus, agrestis, silvestris.</div><div class=\"def\">▼<b>～動物</b> bestia fera.</div><div class=\"def\">⇒<a href=\"entry://野獣\">野獣</a>.</div>\r\n","<div class=\"hw jl\">野菜</div><div class=\"def\">holus, olus.</div><div class=\"def\">▼<b>～栽培家, ～売り</b> holitor.</div><div class=\"def\">▼<b>～園</b> hortus holitorius.</div><div class=\"def\">▼<b>～の</b> holitorius.</div>\r\n","<div class=\"hw jl\">野蛮</div><div class=\"def\">inhumanitas, immanitas, barbaria, feritas.</div><div class=\"def\">▼<b>～な</b> inhumanus, immanis, barbarus, trux, ferus, silvestris.</div>\r\n","<div class=\"hw jl\">量</div><div class=\"def\">quantitas, mensura.</div><div class=\"def\">⇒<a href=\"entry://どれだけ\">どれだけ</a>.</div>\r\n","<div class=\"hw jl\">金</div><div class=\"def\">(=金銭)pecunia, aes, nummi(<i>pl</i>).</div><div class=\"def\">▼<b>～に関する</b> pecuniarius.</div><div class=\"ex2\">利息を取って～を貸す<span class=\"ext\">faenero, faeneror(<i>dep</i>).</span></div><div class=\"def\">⇒<a href=\"entry://金貸し\">金貸し</a>,<a href=\"entry://金持ち\">金持ち</a>,<a href=\"entry://現金\">現金</a>.</div>\r\n","<div class=\"hw jl\">金</div><div class=\"def\">aurum.</div><div class=\"def\">▼<b>～色</b> color aureus.</div><div class=\"def\">▼<b>～の</b> aureus.</div><div class=\"def\">▼<b>～製の</b> ex auro.</div><div class=\"def\">▼<b>～メダル</b> nomisma aureum.</div><div class=\"def\">⇒<a href=\"entry://曜日\">曜日</a>.</div>\r\n","<div class=\"hw jl\">金利</div><div class=\"def\">⇒<a href=\"entry://利子\">利子</a>.</div>\r\n","<div class=\"hw jl\">金属</div><div class=\"def\">metallum.</div><div class=\"def\">▼<b>～の</b> metallicus.</div>\r\n","<div class=\"hw jl\">金庫</div><div class=\"def\">arca, armarium(nummarium).</div><div class=\"def\">▼<b>～に関する</b> arcarius.</div><div class=\"ex2\">鋼鉄製の～<span class=\"ext\">arca ferrata [loricata, munita], armarium loricata [cataphractarium, cataphractatum], pecuniae servandae defendendaeque arca.</span></div><div class=\"ex2\">(銀行などの)鋼鉄製～室<span class=\"ext\">loricata cella, conclave loricatum.</span></div>\r\n","<div class=\"hw jl\">金持ち</div><div class=\"def\">▼<b>～の</b>(=裕福な)dives, pecuniosus, locuples;(特に目立って)praedives.</div><div class=\"def\">⇒<a href=\"entry://豊かな\">豊かな</a>,<a href=\"entry://貧しい\">貧しい</a>.</div>\r\n","<div class=\"hw jl\">金星</div><div class=\"def\">Venus, stella Veneris.</div>\r\n","<div class=\"hw jl\">金融</div><div class=\"def\">res nummaria.</div><div class=\"def\">▼<b>～(上)の</b> pecuniarius, nummarius.</div><div class=\"def\">⇒<a href=\"entry://銀行\">銀行</a>.</div>\r\n","<div class=\"hw jl\">金貨</div><div class=\"def\">aurum, aureus(nummus).</div><div class=\"def\">⇒<a href=\"entry://貨幣\">貨幣</a>.</div>\r\n","<div class=\"hw jl\">金貸し</div><div class=\"def\">(職業)faeneratio;(人)faenerator.</div>\r\n","<div class=\"hw jl\">金銭</div><div class=\"def\">▼<b>～欲</b> nummi amor.</div><div class=\"def\">⇒<a href=\"entry://金\">金<SUB>かね</SUB></a>.</div>\r\n","<div class=\"hw jl\">金額</div><div class=\"def\">pecunia, (pecuniae)summa.</div><div class=\"ex2\">少ない～<span class=\"ext\">parva [mediocris, tenuis] pecunia.</span></div><div class=\"ex2\">大きな～<span class=\"ext\">magna [grandis] pecunia.</span></div>\r\n","<div class=\"hw jl\">金髪</div><div class=\"def\">capillus flavus.</div><div class=\"def\">▼<b>～の</b> flavus.</div><div class=\"ex2\">～の男[少年]<span class=\"ext\">homo [puer] flavus.</span></div><div class=\"ex2\">～の女[少女]<span class=\"ext\">mulier [puella] flava.</span></div>\r\n","<div class=\"hw jl\">釘</div><div class=\"def\">clavus.</div><div class=\"def\">▼<b>小さな～</b> claviculus.</div>\r\n","<div class=\"hw jl\">針</div><div class=\"def\">acus;(時計の)index;(日時計の)gnomon;(秤の)examen.</div>\r\n","<div class=\"hw jl\">釣り</div><div class=\"def\">piscatus, piscatio.</div><div class=\"def\">▼<b>～竿</b> harundo.</div><div class=\"def\">▼<b>～針</b> hamus.</div><div class=\"def\">⇒<a href=\"entry://釣る\">釣る</a>.</div>\r\n","<div class=\"hw jl\">釣る</div><div class=\"def\">piscor(<i>dep</i>).</div><div class=\"ex2\">魚を釣り針で～<span class=\"ext\">pisces hamo capio.</span></div><div class=\"def\">⇒<a href=\"entry://釣り\">釣り</a>.</div>\r\n","<div class=\"hw jl\">鈍い</div><div class=\"def\">(物や心の動きが)tardus, segnis, lentus, hebes, surdus, fuscus, obtusus.</div>\r\n","<div class=\"hw jl\">鉄</div><div class=\"def\">ferrum.</div><div class=\"def\">▼<b>～(製)の</b> ferreus.</div><div class=\"def\">▼<b>～でおおわれた</b> ferratus.</div>\r\n","<div class=\"hw jl\">鉄道</div><div class=\"def\">ferrivia, via ferrata.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">鉄道の駅<span class=\"ext\">statio ferriviae [ferratae viae].</span></div><div class=\"cf\">鉄道の路線<span class=\"ext\">viae ferratae linea.</span></div>\r\n","<div class=\"hw jl\">鉛筆</div><div class=\"def\">lapis scriptorius, plumbatus stilus, graphium, plumbum, haematites.</div><div class=\"def\">▼<b>～削り</b> scriptorii lapidis cuspidamentum, machinula haematitis cuspidandis, instrumentum cuspidarium.</div>\r\n","<div class=\"hw jl\">鉱山</div><div class=\"def\">metallum, fodina.</div>\r\n","<div class=\"hw jl\">鉱物</div><div class=\"def\">res inanima [inanimata], metallum.</div><div class=\"def\">▼<b>～学</b> metallorum doctrina [descriptio], mineralogia.</div><div class=\"def\">▼<b>～の</b> mineralis.</div>\r\n","<div class=\"hw jl\">銀</div><div class=\"def\">argentum.</div><div class=\"def\">▼<b>～の</b> argenteus.</div>\r\n","<div class=\"hw jl\">銀河</div><div class=\"def\">lactea via, lacteus orbis.</div>\r\n","<div class=\"hw jl\">銀行</div><div class=\"def\">argentaria(taberna [mensa]).</div><div class=\"def\">▼<b>～業務</b> argentaria(ars).</div><div class=\"def\">▼<b>～家</b> argentarius.</div><div class=\"def\">▼<b>～口座</b> pecuniae cumulatae depositio.</div><div class=\"def\">▼<b>～(家)の</b> argentarius.</div><div class=\"def\">⇒<a href=\"entry://預金\">預金</a>.</div>\r\n","<div class=\"hw jl\">銀貨</div><div class=\"def\">argentum(signatum), argenteus(nummus).</div><div class=\"def\">⇒<a href=\"entry://貨幣\">貨幣</a>.</div>\r\n","<div class=\"hw jl\">銃</div><div class=\"def\">manuballista(ignivoma), pyroballista.</div><div class=\"def\">⇒<a href=\"entry://拳銃\">拳銃</a>,<a href=\"entry://銃撃\">銃撃</a>.</div>\r\n","<div class=\"hw jl\">銃撃</div><div class=\"def\">ignivomae manuballistae ictus.</div><div class=\"def\">⇒<a href=\"entry://銃\">銃</a>.</div>\r\n","<div class=\"hw jl\">銅</div><div class=\"def\">aes.</div><div class=\"def\">▼<b>～の</b> aereus.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">銅貨<span class=\"ext\">(nummi)aerei(<i>pl</i>).</span></div><div class=\"cf\">銅器<span class=\"ext\">aeramentum.</span></div><div class=\"def\">⇒<a href=\"entry://青銅\">青銅</a>.</div>\r\n","<div class=\"hw jl\">銅貨</div><div class=\"def\">aes(signatum), aereus(nummus).</div><div class=\"def\">⇒<a href=\"entry://貨幣\">貨幣</a>.</div>\r\n","<div class=\"hw jl\">鋭い</div><div class=\"def\">acer.</div>\r\n","<div class=\"hw jl\">鋼鉄</div><div class=\"def\">chalybs.</div><div class=\"def\">▼<b>～の</b> chalybeius.</div>\r\n","<div class=\"hw jl\">錠剤</div><div class=\"def\">pastillus.</div>\r\n","<div class=\"hw jl\">錨</div><div class=\"def\">ancora.</div>\r\n","<div class=\"hw jl\">錯綜</div><div class=\"def\">▼<b>～した</b> tortuosus.</div>\r\n","<div class=\"hw jl\">錯覚</div><div class=\"def\">error, mendacium sensuum.</div><div class=\"def\">⇒<a href=\"entry://幻覚\">幻覚</a>,<a href=\"entry://幻影\">幻影</a>.</div>\r\n","<div class=\"hw jl\">録音</div><div class=\"def\">(磁気テープによる)magnetophonica incisio.</div><div class=\"def\">▼<b>～する</b> in magnetophonio incido.</div>\r\n","<div class=\"hw jl\">鍋</div><div class=\"def\">sartago, caccabus.</div><div class=\"def\">⇒<a href=\"entry://やかん\">やかん</a>.</div>\r\n","<div class=\"hw jl\">鍛える</div><div class=\"def\">(=固くする)duro, induro;(訓練で体を)(=鍛錬する)exerceo, exercito.</div><div class=\"def\">▼<b>鍛えられる</b> induresco.</div><div class=\"def\">⇒<a href=\"entry://訓練\">訓練</a>.</div>\r\n","<div class=\"hw jl\">鍵</div><div class=\"def\">(戸の)clavis;(小さな)clavicula.</div>\r\n","<div class=\"hw jl\">鍵盤</div><div class=\"def\">pinnae(<i>pl</i>);malleori(<i>pl</i>), malleororum series.</div>\r\n","<div class=\"hw jl\">鎖</div><div class=\"def\">catena.</div><div class=\"def\">▼<b>～でつながれた</b> catenatus.</div>\r\n","<div class=\"hw jl\">鏡</div><div class=\"def\">speculum.</div><div class=\"def\">▼<b>～の</b> specularis.</div>\r\n","<div class=\"hw jl\">鐘</div><div class=\"def\">campana.</div><div class=\"ex2\">～の音<span class=\"ext\">campanae vox.</span></div><div class=\"ex2\">夜の～が鳴る<span class=\"ext\">sonat aes nocturnum.</span></div><div class=\"def\">⇒<a href=\"entry://ベル\">ベル</a>.</div>\r\n","<div class=\"hw jl\">長い</div><div class=\"def\">longus, longinquus.</div><div class=\"def\">▼<b>非常に～</b> perlongus.</div><div class=\"def\">▼<b>～間</b> diu, longinquo tempore.</div><div class=\"def\">▼<b>長く</b> longe, diu.</div><div class=\"def\">▼<b>長さ</b> longitudo, longinquitas, proceritas.</div><div class=\"def\">▼<b>時間の～こと</b> diuturnitas.</div><div class=\"def\">⇒<a href=\"entry://短い\">短い</a>.</div>\r\n","<div class=\"hw jl\">長寿</div><div class=\"def\">longaevitas.</div>\r\n","<div class=\"hw jl\">長引く</div><div class=\"def\">perducor(<i>pass</i>), extendor(<i>pass</i>), trahor(<i>pass</i>).</div><div class=\"ex2\">さまざまな話で夜会は長引き, 最も長い一日もすぐに過ぎてしまう<span class=\"ext\">variis sermonibus vespera extenditur, et quamquam longissimus dies bene conditur.</span></div>\r\n","<div class=\"hw jl\">長所</div><div class=\"def\">virtus.</div>\r\n","<div class=\"hw jl\">長持ち</div><div class=\"def\">▼<b>～する</b>(=永続的な)mansurus, permansurus, stabilis, diuturnus.</div>\r\n","<div class=\"hw jl\">門</div><div class=\"def\">porta, janua.</div>\r\n","<div class=\"hw jl\">閉じる</div><div class=\"def\">claudo, occludo.</div><div class=\"def\">▼<b>～こと</b> clausula, occulsio.</div>\r\n","<div class=\"hw jl\">閉じ込める</div><div class=\"def\">concludo, includo, praecludo.</div><div class=\"def\">▼<b>～こと</b> inclusio.</div><div class=\"ex2\">牢獄に～<span class=\"ext\">includo in carcere.</span></div>\r\n","<div class=\"hw jl\">閉まる</div><div class=\"def\">⇒<a href=\"entry://閉める\">閉める</a>.</div>\r\n","<div class=\"hw jl\">閉める</div><div class=\"def\">claudo, obturo.</div><div class=\"def\">⇒<a href=\"entry://閉じる\">閉じる</a>.</div>\r\n","<div class=\"hw jl\">閉店</div><div class=\"def\">tabernae clausula.</div>\r\n","<div class=\"hw jl\">閉鎖</div><div class=\"def\">clausula, obturatio.</div><div class=\"def\">▼<b>～する</b> claudo, obturo.</div>\r\n","<div class=\"hw jl\">開く</div><div class=\"def\">(両開き扉が)(valvae)se aperiunt.</div><div class=\"def\">⇒<a href=\"entry://開ける\">開ける</a>.</div>\r\n","<div class=\"hw jl\">開く</div><div class=\"def\">(花が)(flos)se aperit(← aperio), (flos)dehiscit(← dehisco);(閉じていたものを)aperio;(口を)hio;(会議を)(conventum)celebro.</div>\r\n","<div class=\"hw jl\">開ける</div><div class=\"def\">(戸・門・容器などを)aperio, resero;(大口を)hio.</div>\r\n","<div class=\"hw jl\">開催</div><div class=\"def\">celebratio.</div><div class=\"def\">▼<b>～する</b> celebro, habeo, ago.</div><div class=\"def\">⇒<a href=\"entry://催す\">催す</a>.</div>\r\n","<div class=\"hw jl\">開始</div><div class=\"def\">▼<b>～する</b>(=始める)incoho, incipio.</div>\r\n","<div class=\"hw jl\">開拓者</div><div class=\"def\">(=先駆者, パイオニア)praecursor, procursor, antecursor.</div>\r\n","<div class=\"hw jl\">閏年</div><div class=\"def\">annus bisextus.</div>\r\n","<div class=\"hw jl\">間</div><div class=\"def\">▼(...の)<b> ～に</b> inter 〈+<i>acc</i>〉.</div><div class=\"def\">▼(時間的)<b>その～に</b> dum, interea.</div><div class=\"def\">▼(...している)<b>～に</b> dum 〈+<i>ind</i>〉.</div><div class=\"def\">▼(...している)<b>～は</b> quamdiu 〈+<i>subj</i>〉.</div><div class=\"ex2\">あなたの好きなだけ長い～<span class=\"ext\">quamdiu tu voles.</span></div><div class=\"ex2\">町と村の～に<span class=\"ext\">inter oppidum et vicum.</span></div><div class=\"ex2\">人々の～で<span class=\"ext\">apud populum.</span></div><div class=\"ex2\">3日の～<span class=\"ext\">(per)tres dies.</span></div><div class=\"ex2\">30日の～ずっと<span class=\"ext\">dies continuos triginta.</span></div><div class=\"def\">⇒<a href=\"entry://間隔\">間隔</a>,<a href=\"entry://空間\">空間</a>,<a href=\"entry://時間\">時間</a>.</div>\r\n","<div class=\"hw jl\">間</div><div class=\"def\">⇒<a href=\"entry://間隔\">間隔</a>,<a href=\"entry://時間\">時間</a>,<a href=\"entry://空間\">空間</a>.</div>\r\n","<div class=\"hw jl\">間に合う</div><div class=\"def\">(時間に)in tempore venio, ad tempus [horam] venio;(=十分にある)sufficio, suppedito, satis est.</div><div class=\"def\">▼(定刻に)<b> 間に合って</b> ad tempus.</div><div class=\"def\">⇒<a href=\"entry://遅刻\">遅刻</a>,<a href=\"entry://足りる\">足りる</a>.</div>\r\n","<div class=\"hw jl\">間接</div><div class=\"def\">▼<b>～的な</b> obliquus.</div><div class=\"def\">▼<b>～話法</b> oratio obliqua.</div>\r\n","<div class=\"hw jl\">間違い</div><div class=\"def\">error, erratum, falsum.</div><div class=\"def\">▼<b>書き～</b> mendum.</div><div class=\"def\">▼<b>～の</b> falsus.</div>\r\n","<div class=\"hw jl\">間違える</div><div class=\"def\">(=間違っている)erro, fallor(<i>pass</i>).</div><div class=\"def\">▼<b>間違って</b> falso, per errorem, errore.</div><div class=\"ex2\">誰にでも～ことはある<span class=\"ext\">cujusvis hominis est errare.</span></div><div class=\"ex2\">私が間違っていないならば<span class=\"ext\">nisi fallor/ nisi me forte fallo/ nisi me fallit animus.</span></div><div class=\"ex2\">私が間違っています<span class=\"ext\">erratum est meum.</span></div>\r\n","<div class=\"hw jl\">間隔</div><div class=\"def\">intervallum, distantia.</div><div class=\"def\">⇒<a href=\"entry://間\">間<SUB>あいだ</SUB></a>.</div>\r\n","<div class=\"hw jl\">関して</div><div class=\"def\">(...に)de 〈+<i>abl</i>〉.</div><div class=\"def\">⇒<a href=\"entry://ついて\">ついて</a>.</div>\r\n","<div class=\"hw jl\">関わる・係る</div><div class=\"def\">(=関係する)(...に)pertineo 〈ad+<i>acc</i>〉, attineo 〈ad+<i>acc</i>〉.</div><div class=\"def\">⇒<a href=\"entry://関係\">関係</a>.</div>\r\n","<div class=\"hw jl\">関係</div><div class=\"def\">ratio, colligatio, conjunctio, cognatio.</div><div class=\"def\">▼<b>血縁～</b> cognatio, consanguinitas.</div><div class=\"def\">▼<b>姻戚～</b> affinitas.</div><div class=\"def\">▼(...に)<b> ～する</b> 〈ad+<i>acc</i>〉 pertineo, attineo, attingo.</div><div class=\"def\">▼<b>～のある</b> affinis.</div>\r\n","<div class=\"hw jl\">関心</div><div class=\"def\">(=関心事)studium, cura.</div><div class=\"def\">▼<b>無～</b> incuria, neglectio.</div><div class=\"def\">▼(...に)<b> ～がある</b> 〈+<i>acc</i>〉 curo, curae habeo, 〈+<i>dat</i>〉 studeo.</div>\r\n","<div class=\"hw jl\">関税</div><div class=\"def\">portorium.</div><div class=\"ex2\">～をかける<span class=\"ext\">portorium impono.</span></div><div class=\"ex2\">～を徴収する<span class=\"ext\">portorium exigo.</span></div><div class=\"ex2\">～を払う<span class=\"ext\">portorium do.</span></div><div class=\"def\">⇒<a href=\"entry://税関\">税関</a>.</div>\r\n","<div class=\"hw jl\">関節</div><div class=\"def\">artus, articulus.</div>\r\n","<div class=\"hw jl\">関連</div><div class=\"def\">conjunctio.</div><div class=\"def\">▼<b>～づける</b> conjungo.</div><div class=\"def\">⇒<a href=\"entry://関係\">関係</a>.</div>\r\n","<div class=\"hw jl\">闇</div><div class=\"def\">tenebrae(<i>pl</i>), caligo, nox.</div><div class=\"def\">⇒<a href=\"entry://暗い\">暗い</a>.</div>\r\n","<div class=\"hw jl\">闘争</div><div class=\"def\">luctatio.</div><div class=\"def\">⇒<a href=\"entry://格闘\">格闘</a>,<a href=\"entry://争う\">争う</a>,<a href=\"entry://戦闘\">戦闘</a>.</div>\r\n","<div class=\"hw jl\">闘牛</div><div class=\"def\">tauromachia.</div><div class=\"def\">▼<b>～士</b>(マタドール)mactator.</div>\r\n","<div class=\"hw jl\">防ぐ</div><div class=\"def\">arceo, defendo.</div><div class=\"ex2\">寒さを～ために<span class=\"ext\">frigoris depellendi causā.</span></div><div class=\"def\">⇒<a href=\"entry://防衛\">防衛</a>,<a href=\"entry://防御\">防御</a>.</div>\r\n","<div class=\"hw jl\">防御</div><div class=\"def\">defensio.</div><div class=\"def\">▼<b>～する</b> defendo, tueor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://守る\">守る</a>.</div>\r\n","<div class=\"hw jl\">防止</div><div class=\"def\">▼<b>～する</b>(=防ぐ)praepedio, impedio, prohibeo, praevenio.</div>\r\n","<div class=\"hw jl\">防水</div><div class=\"def\">▼<b>～(加工)</b> immeabile reddens intinctio, illitio immeabilitatem gignens.</div><div class=\"def\">▼(...に)<b> ～(加工)する</b> 〈alqd〉 immeabilem reddo [efficio].</div>\r\n","<div class=\"hw jl\">防衛</div><div class=\"def\">defensio, munimentum.</div><div class=\"def\">▼<b>～する</b> defendo, munio.</div><div class=\"ex2\">沼地と森によって～された場所<span class=\"ext\">locus paludibus silvisque munitus.</span></div>\r\n","<div class=\"hw jl\">阻止</div><div class=\"def\">prohibitio.</div><div class=\"def\">▼<b>～する</b> impedio.</div><div class=\"def\">⇒<a href=\"entry://妨害\">妨害</a>,<a href=\"entry://邪魔\">邪魔</a>.</div>\r\n","<div class=\"hw jl\">降る</div><div class=\"def\">(雨が)pluit(<i>impers</i>);(雪が)ningit(<i>impers</i>), nives cadunt;(良くないことが人に)(=降りかかる)〈ad alqm〉 recido.</div><div class=\"def\">⇒<a href=\"entry://起こる\">起こる</a>.</div>\r\n","<div class=\"hw jl\">降伏</div><div class=\"def\">deditio.</div><div class=\"def\">▼<b>～する</b> in deditionem venio, se dedere(← dedo).</div>\r\n","<div class=\"hw jl\">限り</div><div class=\"def\">▼<b>...である[の]～</b>(ずっと...)(tam diu ...)dum 〈+<i>ind</i>〉.</div><div class=\"def\">▼<b>...しない[でない]～は</b>(=もし...でなければ)nisi ....</div><div class=\"def\">▼(...に)<b>関する～は</b> quantum attinet 〈ad+<i>acc</i>〉.</div><div class=\"ex2\">私の聞いている～では<span class=\"ext\">quantum audio.</span></div><div class=\"ex2\">私の知る～<span class=\"ext\">quantum scio</span></div>\r\n","<div class=\"hw jl\">限る</div><div class=\"def\">(=限界を定める, 制限する, 限定する)finio, termino, definio, determino.</div><div class=\"def\">⇒<a href=\"entry://制限\">制限</a>.</div>\r\n","<div class=\"hw jl\">限定</div><div class=\"def\">▼<b>～する</b> determino, finio, definio.</div>\r\n","<div class=\"hw jl\">限度</div><div class=\"def\">finis.</div><div class=\"ex2\">物事には～がある<span class=\"ext\">est modus in rebus.</span></div>\r\n","<div class=\"hw jl\">限界</div><div class=\"def\">terminus, finis.</div><div class=\"def\">▼<b>～を決める</b> termino, finio.</div>\r\n","<div class=\"hw jl\">陣営</div><div class=\"def\">castra(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">除く</div><div class=\"def\">⇒<a href=\"entry://取り除く\">取り除く</a>,<a href=\"entry://除外\">除外</a>,<a href=\"entry://例外\">例外</a>.</div>\r\n","<div class=\"hw jl\">除外</div><div class=\"def\">exceptio.</div><div class=\"def\">▼<b>～する</b> excipio, excludo.</div><div class=\"def\">⇒<a href=\"entry://例外\">例外</a>.</div>\r\n","<div class=\"hw jl\">陥れる</div><div class=\"def\">(...を)〈alci〉 insidior(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://わな\">わな</a>.</div>\r\n","<div class=\"hw jl\">陰</div><div class=\"def\">umbra.</div><div class=\"def\">▼<b>～の多い</b> umbrosus.</div>\r\n","<div class=\"hw jl\">陰気</div><div class=\"def\">▼<b>～な</b> illaetabilis, tristis, maestus.</div>\r\n","<div class=\"hw jl\">陰謀</div><div class=\"def\">conjuratio, conspiratio.</div><div class=\"def\">▼<b>～者たち</b> conjurati(<i>pl</i>).</div><div class=\"def\">▼<b>～を企てる</b> conjurationem facio, conjuro, conspiro.</div><div class=\"def\">⇒<a href=\"entry://策略\">策略</a>,<a href=\"entry://詐欺\">詐欺</a>,<a href=\"entry://待伏せ\">待伏せ</a>.</div>\r\n","<div class=\"hw jl\">陳列</div><div class=\"def\">dispositio.</div><div class=\"def\">▼<b>～する</b> propono;(売るために)(venditioni)expono.</div><div class=\"def\">▼<b>～された商品</b> merces venditioni expositae.</div>\r\n","<div class=\"hw jl\">陳腐</div><div class=\"def\">▼<b>～な</b> pervagatus, vulgaris, pervulgatus, trivialis, contritus.</div>\r\n","<div class=\"hw jl\">陶器</div><div class=\"def\">figulina opera, figulina(<i>pl</i>).</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">陶工<span class=\"ext\">figulus.</span></div>\r\n","<div class=\"hw jl\">陸</div><div class=\"def\">▼<b>～(地)</b> terra.</div><div class=\"def\">▼<b>～の</b> terrestris, terrenus.</div><div class=\"def\">⇒<a href=\"entry://大陸\">大陸</a>.</div>\r\n","<div class=\"hw jl\">陸上競技</div><div class=\"def\">athletica(<i>pl</i>).</div><div class=\"def\">▼<b>～選手</b> athleta.</div><div class=\"def\">▼<b>～の</b> athleticus.</div>\r\n","<div class=\"hw jl\">険悪</div><div class=\"def\">▼<b>～な</b> minax.</div>\r\n","<div class=\"hw jl\">陽気</div><div class=\"def\">hilaritas, festivitas.</div><div class=\"def\">▼<b>～な</b> hilaris, hilarus, festivus, jocosus.</div><div class=\"def\">▼<b>～に</b> hilare, hilariter, laete.</div>\r\n","<div class=\"hw jl\">階</div><div class=\"def\">(建物の)tabulatum, tabulatio.</div>\r\n","<div class=\"hw jl\">階段</div><div class=\"def\">scalae(<i>pl</i>);(=階段の段)gradus.</div><div class=\"def\">▼<b>螺旋～</b> scalae cochleatae(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">階級</div><div class=\"def\">(社会的な)classis;(=官僚や軍人の位階)gradus, ordo.</div><div class=\"ex2\">～闘争<span class=\"ext\">dimicatio alterius ordinis in alterum.</span></div><div class=\"def\">⇒<a href=\"entry://位\">位</a>.</div>\r\n","<div class=\"hw jl\">随筆</div><div class=\"def\">opusculum altiore doctrina conscriptum [conscribendum].</div><div class=\"def\">▼<b>～家</b> opusculi altioris doctrinae scriptor.</div>\r\n","<div class=\"hw jl\">隔たる</div><div class=\"def\">▼<b>隔たっている</b> disto.</div><div class=\"def\">▼<b>隔たった</b> distans.</div><div class=\"def\">▼<b>隔たり</b> distantia, intervallum, spatium interjectum.</div>\r\n","<div class=\"hw jl\">隕石</div><div class=\"def\">lapis de caelo lapsus.</div>\r\n","<div class=\"hw jl\">障害</div><div class=\"def\">impedimentum, obstructio, vitium;(=障害物)obex.</div><div class=\"ex2\">～物にふさがれた<span class=\"ext\">impeditus.</span></div>\r\n","<div class=\"hw jl\">隠す</div><div class=\"def\">abdo, abscondo, occulto, tego, operio;(正体・本心を)dissimulo.</div><div class=\"def\">▼<b>～こと</b> occultatio.</div>\r\n","<div class=\"hw jl\">隠れる</div><div class=\"def\">se occultare(← occulto), se abdere(← abdo), lateo, delitesco.</div><div class=\"def\">▼<b>隠れている</b> lateo.</div><div class=\"def\">▼<b>隠れて</b> occulte, furtim.</div>\r\n","<div class=\"hw jl\">隠棲</div><div class=\"def\">(=隠遁)secessus, secretum.</div><div class=\"def\">▼<b>～した</b> secretus.</div>\r\n","<div class=\"hw jl\">隠者</div><div class=\"def\">(=隠遁者)eremita.</div><div class=\"def\">⇒<a href=\"entry://隠棲\">隠棲</a>,<a href=\"entry://孤独\">孤独</a>.</div>\r\n","<div class=\"hw jl\">隣</div><div class=\"def\">▼<b>～の</b>(=近隣の)proximus, vicinus, accola, propinquus, finitimus, continens.</div><div class=\"def\">⇒<a href=\"entry://近い\">近い</a>,<a href=\"entry://隣人\">隣人</a>.</div>\r\n","<div class=\"hw jl\">隣りあう</div><div class=\"def\">contingo.</div><div class=\"def\">▼<b>隣りあった</b> conterminus.</div>\r\n","<div class=\"hw jl\">隣人</div><div class=\"def\">proximus(<i>m</i>), vicinus(<i>m</i>), accola.</div>\r\n","<div class=\"hw jl\">隣接</div><div class=\"def\">confinium.</div><div class=\"def\">▼<b>～する, ～した</b> confinis, continens, contiguus.</div>\r\n","<div class=\"hw jl\">雀</div><div class=\"def\">passer.</div>\r\n","<div class=\"hw jl\">雄</div><div class=\"def\">mas.</div><div class=\"def\">▼<b>～の</b> mas, masculus, virilis.</div><div class=\"def\">⇒<a href=\"entry://雌\">雌</a>.</div>\r\n","<div class=\"hw jl\">雄大</div><div class=\"def\">▼<b>～(さ)</b> granditas, majestas, amplitudo.</div><div class=\"def\">▼<b>～な</b> grandis, amplus, magnus.</div>\r\n","<div class=\"hw jl\">雄弁</div><div class=\"def\">eloquentia, facundia, dicendi [in dicendo] facultas, eloquendi vis.</div><div class=\"def\">▼<b>～な</b> eloquens, facundus.</div><div class=\"def\">▼<b>～に</b> facunde, eloquenter, disserte.</div>\r\n","<div class=\"hw jl\">集まり</div><div class=\"def\">concilium, conventus, congressus, congregatio.</div><div class=\"def\">⇒<a href=\"entry://集会\">集会</a>.</div>\r\n","<div class=\"hw jl\">集まる</div><div class=\"def\">convenio, coeo, congregor(<i>dep</i>), se congregare(← congrego), congredior(<i>dep</i>);(=人々が集まってくる)coitur(<i>impers pass</i>).</div>\r\n","<div class=\"hw jl\">集める</div><div class=\"def\">confero, cogo, colligo, colloco, compono.</div><div class=\"ex2\">1か所に～<span class=\"ext\">in unum locum conduco.</span></div>\r\n","<div class=\"hw jl\">集中</div><div class=\"def\">(注意力の)intentio.</div><div class=\"def\">▼<b>～する</b>(=一か所に集める)in unum locum cogo;(精神を)intendo.</div><div class=\"def\">▼<b>精神を～させた</b> intentus.</div><div class=\"ex2\">(...に)精神を～する<span class=\"ext\">animum 〈in alqd〉 intendo.</span></div><div class=\"ex2\">すべての権力がひとりの人に～しているとき, 私たちはそのひとりの人を王と呼ぶ<span class=\"ext\">cum penes unum est omnium summa rerum, regem illum unum vocamus.</span></div>\r\n","<div class=\"hw jl\">集会</div><div class=\"def\">conventus, congressus, concilium, coetus.</div>\r\n","<div class=\"hw jl\">集合</div><div class=\"def\">conventus, conventio.</div><div class=\"def\">▼<b>～する</b> convenio, congregor(<i>pass</i>), cogor(<i>pass</i>).</div>\r\n","<div class=\"hw jl\">集団</div><div class=\"def\">turba, grex, globus, circulus.</div><div class=\"def\">⇒<a href=\"entry://群れ\">群れ</a>.</div>\r\n","<div class=\"hw jl\">雇う</div><div class=\"def\">adhibeo, utor(<i>dep</i>), in usu habeo, auctoro.</div>\r\n","<div class=\"hw jl\">雇用</div><div class=\"def\">opus, munus.</div><div class=\"def\">▼<b>～者</b> operum conductores(<i>pl</i>).</div><div class=\"def\">▼<b>被～者</b> opifices(<i>pl</i>), operarii(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://労働\">労働</a>,<a href=\"entry://雇う\">雇う</a>.</div>\r\n","<div class=\"hw jl\">雌</div><div class=\"def\">femina.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">雌蛇<span class=\"ext\">serpens femina.</span></div><div class=\"cf\">雌鴨<span class=\"ext\">anas femina.</span></div><div class=\"def\">⇒<a href=\"entry://雄\">雄</a>.</div>\r\n","<div class=\"hw jl\">雑誌</div><div class=\"def\">commentarii periodici(<i>pl</i>), acta periodica(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">雑談</div><div class=\"def\">fabulae(<i>pl</i>).</div><div class=\"ex2\">～で時間をつぶす<span class=\"ext\">tempus fabulis contero.</span></div><div class=\"def\">⇒<a href=\"entry://おしゃべり\">おしゃべり</a>.</div>\r\n","<div class=\"hw jl\">雑踏</div><div class=\"def\">turba.</div>\r\n","<div class=\"hw jl\">離す</div><div class=\"def\">separo, sejungo, discludo, disjungo, semoveo.</div>\r\n","<div class=\"hw jl\">離れている</div><div class=\"def\">disto, absum.</div><div class=\"ex2\">(それは)ローマから30キロ～<span class=\"ext\">a Roma triginta chiliometra distat.</span></div>\r\n","<div class=\"hw jl\">離れる</div><div class=\"def\">relinquo, discedo, recedo, abeo.</div><div class=\"ex2\">公職から～<span class=\"ext\">se a negotiis publicis removere(← removeo).</span></div><div class=\"def\">⇒<a href=\"entry://離す\">離す</a>.</div>\r\n","<div class=\"hw jl\">離婚</div><div class=\"def\">divortium, discidium.</div><div class=\"def\">▼(相手と)<b> ～する</b> 〈cum alqo〉 divortium facio, diverto;(夫から)(a marito)digredior(<i>dep</i>).</div><div class=\"def\">▼(妻に)<b>～を通告する</b>(uxori)nuntium remitto.</div><div class=\"def\">⇒<a href=\"entry://離縁\">離縁</a>.</div>\r\n","<div class=\"hw jl\">離縁</div><div class=\"def\">▼(夫が妻を)<b>～する</b> repudio.</div><div class=\"def\">⇒<a href=\"entry://離婚\">離婚</a>.</div>\r\n","<div class=\"hw jl\">離陸</div><div class=\"def\">(飛行機の)avolatio.</div><div class=\"def\">▼<b>～する</b> avolo, evolo, (ad caelum)extollor(<i>pass</i>), a terra se removere(← removeo).</div>\r\n","<div class=\"hw jl\">難しい</div><div class=\"def\">(=困難な)difficilis, haud facilis;(...することは)difficile est 〈+<i>inf</i>〉.</div>\r\n","<div class=\"hw jl\">難儀</div><div class=\"def\">aerumna, labor.</div><div class=\"def\">▼<b>～の多い</b> aerumnosus.</div><div class=\"def\">▼<b>～する</b> laboro.</div>\r\n","<div class=\"hw jl\">難民</div><div class=\"def\">fugitivus, profugus, exsul hospitio receptus, advena asylo donatus.</div><div class=\"def\">▼<b>～収容所</b> campus receptorius profugorum [profugis recipiendis].</div>\r\n","<div class=\"hw jl\">雨</div><div class=\"def\">pluvia, imber.</div><div class=\"def\">▼<b>～の</b> pluvius.</div><div class=\"def\">▼<b>～が降る</b> pluit(<i>impers</i>).</div>\r\n","<div class=\"hw jl\">雨期</div><div class=\"def\">tempus pluviae.</div>\r\n","<div class=\"hw jl\">雪</div><div class=\"def\">nix.</div><div class=\"def\">▼<b>～が降る</b> ningit(<i>impers</i>), nives cadunt(← cado).</div><div class=\"ex2\">非常に深い～<span class=\"ext\">altissima nix.</span></div>\r\n","<div class=\"hw jl\">雪崩</div><div class=\"def\">labina, nivis labes, nivium moles decidens, nives(de monte)devolutae(<i>pl</i>), nivalis ruina, praeceps nivium lapsus.</div>\r\n","<div class=\"hw jl\">雰囲気</div><div class=\"def\">(=気分)animi affectus [habitus], ambitūs condicio;(=空気)aer.</div><div class=\"def\">⇒<a href=\"entry://大気\">大気</a>.</div>\r\n","<div class=\"hw jl\">雲</div><div class=\"def\">nubes, nubilum.</div><div class=\"def\">⇒<a href=\"entry://曇る\">曇る</a>.</div>\r\n","<div class=\"hw jl\">雷</div><div class=\"def\">fulmen;(=雷光, 稲光)fulgur;(=雷鳴)tonitrus.</div><div class=\"ex2\">～が鳴る<span class=\"ext\">tonat(<i>impers</i>).</span></div>\r\n","<div class=\"hw jl\">電力</div><div class=\"def\">electrica vis.</div>\r\n","<div class=\"hw jl\">電卓</div><div class=\"def\">machinula calculatoria.</div>\r\n","<div class=\"hw jl\">電報</div><div class=\"def\">telegramma.</div>\r\n","<div class=\"hw jl\">電子</div><div class=\"def\">electro.</div><div class=\"def\">▼<b>～の</b> electronicus.</div>\r\n","<div class=\"hw jl\">電子メール</div><div class=\"def\">⇒<a href=\"entry://Eメール\">Eメール</a>.</div>\r\n","<div class=\"hw jl\">電気</div><div class=\"def\">electris;(=電力)electrica vis.</div><div class=\"def\">▼<b>～の</b> electricus.</div>\r\n","<div class=\"hw jl\">電池</div><div class=\"def\">pila electrica;(=蓄電池)instrumentum electridi cumulandae.</div>\r\n","<div class=\"hw jl\">電波</div><div class=\"def\">unda electromagnetica [radiophonica, Hertziana].</div>\r\n","<div class=\"hw jl\">電流</div><div class=\"def\">⇒<a href=\"entry://電気\">電気</a>.</div>\r\n","<div class=\"hw jl\">電燈</div><div class=\"def\">lanterna(electrica).</div>\r\n","<div class=\"hw jl\">電線</div><div class=\"def\">(=送電線)funis electricus, electroductus;(=電気コード)linea electrica.</div>\r\n","<div class=\"hw jl\">電話</div><div class=\"def\">telephonium, telephonum.</div><div class=\"def\">▼<b>～で</b> per telephonum.</div><div class=\"def\">▼<b>～する</b> telephonice [per telephonium] colloquor(<i>dep</i>).</div><div class=\"def\">▼<b>～機</b> apparatus telephonicus.</div><div class=\"def\">▼<b>～番号</b> numerus telephonicus.</div>\r\n","<div class=\"hw jl\">需要</div><div class=\"def\">quod opus est.</div>\r\n","<div class=\"hw jl\">震える</div><div class=\"def\">tremo, intremo, se tremefacere(← tremefacio);(激しく)contremo.</div>\r\n","<div class=\"hw jl\">霊</div><div class=\"def\">(=霊魂, 魂)animus, anima, spiritus.</div><div class=\"def\">⇒<a href=\"entry://精神\">精神</a>,<a href=\"entry://幽霊\">幽霊</a>.</div>\r\n","<div class=\"hw jl\">霜</div><div class=\"def\">pruina.</div><div class=\"def\">▼<b>～の降りた, ～でおおわれた</b> pruinosus.</div>\r\n","<div class=\"hw jl\">霧</div><div class=\"def\">nebula, caligo.</div><div class=\"def\">▼<b>～深い, ～のかかった</b> nebulosus, caliginosus.</div>\r\n","<div class=\"hw jl\">青</div><div class=\"def\">▼(空のように)<b> ～い</b> caeruleus.</div><div class=\"def\">▼<b>～い色</b> caeruleus color.</div>\r\n","<div class=\"hw jl\">青ざめる</div><div class=\"def\">palleo, pallesco.</div><div class=\"def\">▼<b>青ざめた</b> pallens, exsanguis.</div>\r\n","<div class=\"hw jl\">青年</div><div class=\"def\">juvenis, adulescens.</div><div class=\"def\">▼<b>～時代</b> adulescentia, juventa, juventas.</div><div class=\"def\">▼<b>～の</b> juvenis, juvenilis.</div><div class=\"def\">⇒<a href=\"entry://青春\">青春</a>.</div>\r\n","<div class=\"hw jl\">青春</div><div class=\"def\">juventus, juventas.</div><div class=\"def\">▼<b>～の女神</b> Hebe.</div>\r\n","<div class=\"hw jl\">青銅</div><div class=\"def\">aes.</div><div class=\"def\">▼<b>～の</b> aeneus, aereus.</div>\r\n","<div class=\"hw jl\">静か</div><div class=\"def\">▼<b>～な</b> tacitus, silens, tranquillus, placidus, quietus.</div><div class=\"def\">▼<b>～に</b> tacite, placide, quiete, tranquille.</div><div class=\"def\">⇒<a href=\"entry://無口\">無口</a>,<a href=\"entry://平静\">平静</a>.</div>\r\n","<div class=\"hw jl\">静けさ</div><div class=\"def\">silentium, tranquillitas.</div>\r\n","<div class=\"hw jl\">静まる</div><div class=\"def\">silesco, sedor(<i>pass</i>), quiesco, placor(<i>pass</i>).</div>\r\n","<div class=\"hw jl\">静める</div><div class=\"def\">sedo, placo, restinguo.</div>\r\n","<div class=\"hw jl\">静寂</div><div class=\"def\">quies.</div><div class=\"def\">⇒<a href=\"entry://静か\">静か</a>.</div>\r\n","<div class=\"hw jl\">静脈</div><div class=\"def\">vena.</div><div class=\"def\">⇒<a href=\"entry://動脈\">動脈</a>,<a href=\"entry://血管\">血管</a>.</div>\r\n","<div class=\"hw jl\">非常に</div><div class=\"def\">multum, maxime, valde, longe, perquam, admodum, magnopere(一般に形容詞と副詞の最上級を用いる).</div>\r\n","<div class=\"hw jl\">非常口</div><div class=\"def\">exitus saluti prospiciendae.</div>\r\n","<div class=\"hw jl\">非難</div><div class=\"def\">objectio, objectatio, exprobratio, reprehensio, culpatio, vituperatio, accusatio.</div><div class=\"def\">▼<b>～する</b> obicio, objecto, exprobro, reprehendo, culpo, vitupero, accuso.</div>\r\n","<div class=\"hw jl\">面</div><div class=\"def\">(=マスク)persona, larva.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">顔面<span class=\"ext\">facies.</span></div><div class=\"cf\">表面<span class=\"ext\">superficies.</span></div><div class=\"cf\">水面<span class=\"ext\">aquae superficies, summa aqua.</span></div><div class=\"cf\">地面<span class=\"ext\">summum solum, summa humus.</span></div><div class=\"cf\">側面<span class=\"ext\">latus.</span></div><div class=\"cf\">前面<span class=\"ext\">frons.</span></div>\r\n","<div class=\"hw jl\">面して</div><div class=\"def\">(...に)adversus 〈+<i>acc</i>〉.</div>\r\n","<div class=\"hw jl\">面する</div><div class=\"ex2\">通りに～窓<span class=\"ext\">fenestrae in viam versae(<i>pl</i>).</span></div><div class=\"ex2\">寝室が山に面している<span class=\"ext\">cubiculum montes intuetur.</span></div>\r\n","<div class=\"hw jl\">面会</div><div class=\"def\">(=会見, 会談)congressus, colloquium;(=訪問)salutatio.</div>\r\n","<div class=\"hw jl\">面倒</div><div class=\"def\">(=煩わしさ)molestia, difficultas;(=世話)cura.</div><div class=\"def\">▼<b>～な</b>(=煩わしい)molestus, gravis, difficilis.</div>\r\n","<div class=\"hw jl\">面目</div><div class=\"def\">honestas, existimatio, fama.</div><div class=\"def\">▼<b>不～</b> infamia.</div><div class=\"def\">▼<b>不～な</b> inhonestus, turpis.</div><div class=\"def\">⇒<a href=\"entry://名誉\">名誉</a>,<a href=\"entry://名声\">名声</a>.</div>\r\n","<div class=\"hw jl\">面積</div><div class=\"def\">superficies.</div>\r\n","<div class=\"hw jl\">革・皮</div><div class=\"def\">cutis, corium.</div><div class=\"def\">⇒<a href=\"entry://毛皮\">毛皮</a>.</div>\r\n","<div class=\"hw jl\">革命</div><div class=\"def\">(政体の)res novae(<i>pl</i>);(=政体の変化)rei publicae commutatio.</div><div class=\"ex2\">～を企てる<span class=\"ext\">novis rebus studeo, novas res molior(<i>dep</i>).</span></div><div class=\"ex2\">～を起こす<span class=\"ext\">seditionem moveo.</span></div>\r\n","<div class=\"hw jl\">靴</div><div class=\"def\">calcei(<i>pl</i>), calceamenta(<i>pl</i>).</div><div class=\"def\">▼<b>～屋</b> sutor, calceolarius.</div><div class=\"ex2\">～を履く<span class=\"ext\">se calceare(← calceo)/ calceamenta induo.</span></div><div class=\"ex2\">～を履きかえる<span class=\"ext\">calceos muto.</span></div><div class=\"def\">⇒<a href=\"entry://靴ひも\">靴ひも</a>.</div>\r\n","<div class=\"hw jl\">靴ひも</div><div class=\"def\">corrigia.</div>\r\n","<div class=\"hw jl\">鞄</div><div class=\"def\">(=袋)saccus, folliculus;(旅行用の)mantica.</div>\r\n","<div class=\"hw jl\">鞭</div><div class=\"def\">flagellum, flagrum, verber, lorum, virga.</div><div class=\"def\">▼<b>～で打つ</b> verbero, verberibus [flagellis, loris] caedo, flagello.</div>\r\n","<div class=\"hw jl\">韓国</div><div class=\"def\">(=大韓民国)Corea Meridionalis [Meridiana].</div><div class=\"def\">▼<b>～(人)の</b> Coreanus meridionalis.</div><div class=\"def\">▼<b>～人</b> Coreani meridionales(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">音</div><div class=\"def\">sonus, sonitus, sonor.</div><div class=\"ex2\">～でいっぱいの(=やかましい)<span class=\"ext\">sonorus, sonans.</span></div><div class=\"ex2\">～をたてる<span class=\"ext\">sono.</span></div>\r\n","<div class=\"hw jl\">音楽</div><div class=\"def\">musica.</div><div class=\"def\">▼<b>～家</b> musicus.</div><div class=\"def\">▼<b>～の</b> musicus, symphoniacus.</div>\r\n","<div class=\"hw jl\">音波</div><div class=\"def\">(=音の波, 可聴な波)unda sonora, unda audibilis, unda acustica.</div>\r\n","<div class=\"hw jl\">韻律</div><div class=\"def\">metrum.</div><div class=\"def\">▼<b>～学</b> metrorum scientia.</div>\r\n","<div class=\"hw jl\">韻文</div><div class=\"def\">versus, carmen, poema.</div><div class=\"def\">⇒<a href=\"entry://散文\">散文</a>.</div>\r\n","<div class=\"hw jl\">響く</div><div class=\"def\"><span class=\"pos3\">[動]</span> resono.</div><div class=\"def\">━<span class=\"pos3\">[形]</span> resonans.</div><div class=\"def\">▼<b>響き</b> resonantia.</div>\r\n","<div class=\"hw jl\">頂</div><div class=\"def\">cacumen, culmen, fastigium, vertex.</div>\r\n","<div class=\"hw jl\">頂上</div><div class=\"def\">fastigium;(山の)summus mons, montis summum jugum.</div><div class=\"def\">⇒<a href=\"entry://最高峰\">最高峰</a>,<a href=\"entry://頂\">頂</a>,<a href=\"entry://頂点\">頂点</a>.</div>\r\n","<div class=\"hw jl\">頂点</div><div class=\"ex2\">天の～<span class=\"ext\">caeli [mundi] fastigium.</span></div><div class=\"def\">⇒<a href=\"entry://頂\">頂</a>.</div>\r\n","<div class=\"hw jl\">頃</div><div class=\"def\">▼(...の)<b> ～(に)</b> ad 〈+<i>acc</i>〉, sub 〈+<i>acc</i>〉, circa 〈+<i>acc</i>〉.</div><div class=\"ex2\">(第)1時～<span class=\"ext\">circa primam horam.</span></div><div class=\"ex2\">夜明け～<span class=\"ext\">ad lucem.</span></div><div class=\"ex2\">5時～<span class=\"ext\">quinta fere hora.</span></div><div class=\"ex2\">何時～に<span class=\"ext\">ad quam horam ...?</span></div><div class=\"ex2\">お昼～<span class=\"ext\">circiter meridiem.</span></div><div class=\"ex2\">ほぼ同時刻～<span class=\"ext\">circa eandem horam.</span></div>\r\n","<div class=\"hw jl\">項目</div><div class=\"def\">caput, articulus.</div>\r\n","<div class=\"hw jl\">順序</div><div class=\"def\">ordo.</div><div class=\"def\">▼<b>～正しく</b> ordinatim, ordine, in [ex] ordine, in [per] ordinem.</div><div class=\"ex2\">～正しく並べる<span class=\"ext\">ordino.</span></div>\r\n","<div class=\"hw jl\">順番</div><div class=\"def\">ordo.</div><div class=\"def\">▼<b>～に</b> alium post alium.</div><div class=\"def\">⇒<a href=\"entry://代わるがわる\">代わるがわる</a>,<a href=\"entry://番\">番</a>.</div>\r\n","<div class=\"hw jl\">順調</div><div class=\"def\">▼<b>～に</b> bene.</div><div class=\"ex2\">～に進む<span class=\"ext\">bene succedo [procedo].</span></div>\r\n","<div class=\"hw jl\">預かる</div><div class=\"def\">(=預けられたものを受け取り保管する)accipio, conservo depositum.</div><div class=\"def\">⇒<a href=\"entry://預ける\">預ける</a>.</div>\r\n","<div class=\"hw jl\">預ける</div><div class=\"def\">depono.</div>\r\n","<div class=\"hw jl\">預金</div><div class=\"def\">▼<b>～する</b>(pecuniam)depono, (pecuniam)in tutum pono, (pecuniam)custodiae trado.</div><div class=\"def\">▼(銀行の)<b>～口座</b> pecuniae cumulatae depositio.</div><div class=\"def\">▼<b>～通帳</b> libellus pecuniae.</div>\r\n","<div class=\"hw jl\">頑固</div><div class=\"def\">pertinacia, obstinatio.</div><div class=\"def\">▼<b>～な</b> pertinax, obstinatus, firmus.</div><div class=\"ex2\">彼はますます～になった<span class=\"ext\">magis ac magis induruit.</span></div><div class=\"def\">⇒<a href=\"entry://意地\">意地</a>.</div>\r\n","<div class=\"hw jl\">領収</div><div class=\"def\">acceptio.</div><div class=\"def\">▼<b>～書</b> apocha(solutae pecuniae).</div><div class=\"def\">▼(金銭を)<b> ～する</b>(pecuniam)accipio.</div><div class=\"ex2\">(...について)～書を書く<span class=\"ext\">〈in alqd〉 pecuniam acceptam refero.</span></div>\r\n","<div class=\"hw jl\">領土</div><div class=\"def\">fines(<i>pl</i>), ager, solum, terra.</div>\r\n","<div class=\"hw jl\">領地</div><div class=\"def\">fundus, praedium.</div>\r\n","<div class=\"hw jl\">領域</div><div class=\"def\">regio.</div><div class=\"ex2\">多くの～で<span class=\"ext\">in pluribus rebus.</span></div><div class=\"def\">⇒<a href=\"entry://領地\">領地</a>,<a href=\"entry://領土\">領土</a>.</div>\r\n","<div class=\"hw jl\">頬</div><div class=\"def\">gena.</div>\r\n","<div class=\"hw jl\">頭</div><div class=\"def\">caput.</div>\r\n","<div class=\"hw jl\">頭脳</div><div class=\"def\">cerebrum.</div>\r\n","<div class=\"hw jl\">頻繁</div><div class=\"def\">crebritas, frequentia.</div><div class=\"def\">▼<b>～な</b> creber.</div><div class=\"def\">▼<b>～に</b> crebro, saepe, frequenter.</div><div class=\"def\">▼<b>非常に～に</b> persaepe.</div><div class=\"def\">▼<b>～になる</b> crebresco.</div><div class=\"def\">⇒<a href=\"entry://しばしば\">しばしば</a>,<a href=\"entry://たびたび\">たびたび</a>.</div>\r\n","<div class=\"hw jl\">頼む</div><div class=\"def\">rogo, quaeso.</div><div class=\"def\">▼<b>～こと</b> rogatio.</div><div class=\"def\">⇒<a href=\"entry://催促\">催促</a>,<a href=\"entry://請願\">請願</a>,<a href=\"entry://要求\">要求</a>,<a href=\"entry://懇願\">懇願</a>,<a href=\"entry://嘆願\">嘆願</a>.</div>\r\n","<div class=\"hw jl\">頼る</div><div class=\"def\">recurro, decurro.</div><div class=\"def\">⇒<a href=\"entry://信頼\">信頼</a>.</div>\r\n","<div class=\"hw jl\">題</div><div class=\"def\">(=表題)titulus, index, inscriptio.</div><div class=\"def\">⇒<a href=\"entry://主題\">主題</a>.</div>\r\n","<div class=\"hw jl\">額</div><div class=\"def\">(=金額)pecunia.</div><div class=\"def\">▼<b>総～</b> summa.</div><div class=\"def\">⇒<a href=\"entry://額縁\">額縁</a>.</div>\r\n","<div class=\"hw jl\">額</div><div class=\"def\">frons.</div>\r\n","<div class=\"hw jl\">額縁</div><div class=\"def\">forma.</div><div class=\"ex2\">(絵を)～に入れる<span class=\"ext\">(picturam)in forma includo.</span></div><div class=\"ex2\">木の～に入れる<span class=\"ext\">ligneis formis includo.</span></div>\r\n","<div class=\"hw jl\">顔</div><div class=\"def\">facies, vultus, os, frons.</div>\r\n","<div class=\"hw jl\">顔つき</div><div class=\"def\">(=顔の特徴)oris lineamenta(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">顔料</div><div class=\"def\">(=染料)pigmentum.</div><div class=\"def\">⇒<a href=\"entry://インク\">インク</a>.</div>\r\n","<div class=\"hw jl\">顔色</div><div class=\"def\">color, facies.</div><div class=\"def\">▼<b>～の悪い</b> pallidus.</div>\r\n","<div class=\"hw jl\">願い</div><div class=\"def\">optatum, votum.</div>\r\n","<div class=\"hw jl\">願う</div><div class=\"def\">(=望む)opto, exopto, voveo;(=懇願する)oro;(=切望する)cupio;(=依頼する)rogo.</div><div class=\"def\">▼(どうか)<b>お願いです</b> quaeso.</div>\r\n","<div class=\"hw jl\">願書</div><div class=\"def\">⇒<a href=\"entry://請願\">請願</a>.</div>\r\n","<div class=\"hw jl\">願望</div><div class=\"def\">optatum, votum.</div><div class=\"def\">⇒<a href=\"entry://願う\">願う</a>.</div>\r\n","<div class=\"hw jl\">類</div><div class=\"def\">genus.</div><div class=\"def\">⇒<a href=\"entry://種\">種<SUB>しゅ</SUB></a>.</div>\r\n","<div class=\"hw jl\">類似</div><div class=\"def\">similitudo, vicinitas.</div><div class=\"def\">▼<b>～の</b> similis, vicinus.</div>\r\n","<div class=\"hw jl\">類推</div><div class=\"def\">analogia, comparatio, proportio.</div><div class=\"def\">▼<b>～によって</b> per analogiam.</div>\r\n","<div class=\"hw jl\">顧問</div><div class=\"def\">consultor(<i>m</i>), consiliarius(<i>m</i>).</div><div class=\"def\">⇒<a href=\"entry://助言\">助言</a>,<a href=\"entry://相談\">相談</a>.</div>\r\n","<div class=\"hw jl\">風</div><div class=\"def\">ventus, spiritus.</div><div class=\"def\">▼<b>北～</b> aquilo, boreas.</div><div class=\"def\">▼<b>南～</b> auster, notus.</div><div class=\"def\">▼<b>東～</b> eurus.</div><div class=\"def\">▼<b>西～</b> zephyrus.</div>\r\n","<div class=\"hw jl\">風</div><div class=\"def\">(=風習, やり方)mos, modus, ritus.</div>\r\n","<div class=\"hw jl\">風俗</div><div class=\"def\">(=風習, 習慣)mos, cultus, consuetudo.</div>\r\n","<div class=\"hw jl\">風呂</div><div class=\"def\">(=浴槽)solium, alveus;(=浴室)balneum;(=浴場, 温泉)balneae(<i>pl</i>), thermae(<i>pl</i>).</div><div class=\"def\">▼<b>サウナ～</b> sudatorium, laconicum.</div>\r\n","<div class=\"hw jl\">風土</div><div class=\"def\">caelum.</div>\r\n","<div class=\"hw jl\">風景</div><div class=\"def\">regionis forma.</div><div class=\"def\">▼<b>美しい～</b> locorum amoenitas.</div><div class=\"def\">▼<b>～画</b> topia(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://景色\">景色</a>.</div>\r\n","<div class=\"hw jl\">風邪</div><div class=\"def\">(=鼻風邪)gravedo, destillatio narium.</div><div class=\"def\">▼<b>～をひいている</b> gravedinosus.</div>\r\n","<div class=\"hw jl\">飛ばす</div><div class=\"def\">(投げて)jacio, jaculor(<i>dep</i>), jacto.</div><div class=\"def\">▼<b>～こと</b> jactatio, jactus.</div>\r\n","<div class=\"hw jl\">飛び回る</div><div class=\"def\"><span class=\"pos3\">[動]</span> volito.</div><div class=\"def\">━<span class=\"pos3\">[形]</span> volaticus, volatilis.</div><div class=\"def\">▼<b>～こと</b> volatus.</div>\r\n","<div class=\"hw jl\">飛び越える</div><div class=\"def\">transilio.</div>\r\n","<div class=\"hw jl\">飛び込む</div><div class=\"def\">(...に)〈in+<i>acc</i>〉 se abicere(← abicio), se conjicere(← conjicio);(まっさかさまに)praecipito.</div>\r\n","<div class=\"hw jl\">飛ぶ</div><div class=\"def\">volo.</div>\r\n","<div class=\"hw jl\">飛行</div><div class=\"def\">volatus, volatio.</div><div class=\"def\">▼<b>～する</b> volo, volatum facio.</div><div class=\"def\">⇒<a href=\"entry://飛ぶ\">飛ぶ</a>.</div>\r\n","<div class=\"hw jl\">飛行場</div><div class=\"def\">statio aeronautica, aeroportus.</div>\r\n","<div class=\"hw jl\">飛行機</div><div class=\"def\">aeronavis, aerovehiculum, aeroplanum.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">戦闘機<span class=\"ext\">aeroplanum militarium.</span></div><div class=\"cf\">輸送機<span class=\"ext\">aeroplanum onerarium.</span></div>\r\n","<div class=\"hw jl\">飛躍</div><div class=\"def\">saltus.</div><div class=\"def\">▼<b>～する</b> salio.</div>\r\n","<div class=\"hw jl\">食いしん坊</div><div class=\"def\">homo edax(<i>m</i>), mulier edax(<i>f</i>).</div><div class=\"def\">▼<b>～の</b> gulosus, edax, deditus gulae, deditus ventri.</div><div class=\"def\">⇒<a href=\"entry://美食\">美食</a>.</div>\r\n","<div class=\"hw jl\">食い違い</div><div class=\"def\">▼(意見の)(=不一致)discrepantia, discordia, dissensio, dissensus.</div><div class=\"def\">▼(意見が)<b> 食い違う</b>(=一致しない)discrepo, dissentio.</div><div class=\"def\">▼<b>～がある</b> disconvenio.</div><div class=\"def\">▼(意見の)<b> 食い違った</b> discors, dissentaneus.</div>\r\n","<div class=\"hw jl\">食べる</div><div class=\"def\">edo, sumo, vescor(<i>dep</i>).</div><div class=\"def\">▼<b>食べ尽くす</b> comedo.</div><div class=\"def\">▼<b>味わって～</b> gusto.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">むさぼり食う<span class=\"ext\">voro, devoro.</span></div>\r\n","<div class=\"hw jl\">食べ物</div><div class=\"def\">cibus, esculenta(<i>pl</i>), alimentum, esca, cibaria(<i>pl</i>), victus.</div><div class=\"def\">▼<b>～の</b> cibarius, alimentarius.</div>\r\n","<div class=\"hw jl\">食事</div><div class=\"def\">cibus, mensa.</div><div class=\"ex2\">～を取る<span class=\"ext\">cibum capio.</span></div><div class=\"def\">⇒<a href=\"entry://朝食\">朝食</a>,<a href=\"entry://昼食\">昼食</a>,<a href=\"entry://夕食\">夕食</a>.</div>\r\n","<div class=\"hw jl\">食卓</div><div class=\"def\">mensa, escaria mensa.</div>\r\n","<div class=\"hw jl\">食品</div><div class=\"def\">⇒<a href=\"entry://食料\">食料</a>.</div>\r\n","<div class=\"hw jl\">食器</div><div class=\"def\">vas, escaria(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">食料</div><div class=\"def\">victus, alimentum, cibus.</div><div class=\"def\">▼<b>～に関する</b> cibarius.</div><div class=\"def\">⇒<a href=\"entry://食物\">食物</a>.</div>\r\n","<div class=\"hw jl\">食欲</div><div class=\"def\">cibi aviditas [cupiditas].</div>\r\n","<div class=\"hw jl\">食物</div><div class=\"def\">cibus, alimentum, esca.</div><div class=\"def\">▼<b>～の</b> cibarius, alimentarius.</div>\r\n","<div class=\"hw jl\">食通</div><div class=\"def\">⇒<a href=\"entry://美食\">美食</a>.</div>\r\n","<div class=\"hw jl\">食道</div><div class=\"def\">gula.</div>\r\n","<div class=\"hw jl\">飢える</div><div class=\"def\">esurio.</div><div class=\"def\">▼<b>飢え</b> fames, inedia, esuritio.</div><div class=\"def\">▼<b>飢え死にする</b> fame morior(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://飢餓\">飢餓</a>.</div>\r\n","<div class=\"hw jl\">飢餓</div><div class=\"def\">(=飢え)fames, cibi inopia [penuria], annonae inopia [penuria].</div>\r\n","<div class=\"hw jl\">飢饉</div><div class=\"def\">⇒<a href=\"entry://飢餓\">飢餓</a>.</div>\r\n","<div class=\"hw jl\">飯台</div><div class=\"def\">escaria mensa.</div>\r\n","<div class=\"hw jl\">飲み干す</div><div class=\"def\">exhaurio, haurio.</div>\r\n","<div class=\"hw jl\">飲み物</div><div class=\"def\">potio, potus, potulentum, sorbitio.</div>\r\n","<div class=\"hw jl\">飲み込む</div><div class=\"def\">sorbeo, absorbeo, devoro, haurio, glutio.</div>\r\n","<div class=\"hw jl\">飲む</div><div class=\"def\">bibo, poto;(薬を)(=服用する)sumo.</div><div class=\"def\">▼<b>～こと</b> potio, potus.</div><div class=\"ex2\">仲間と一緒に～<span class=\"ext\">combibo.</span></div>\r\n","<div class=\"hw jl\">飲食</div><div class=\"def\">(=食べることと飲むこと)cibus et potio.</div>\r\n","<div class=\"hw jl\">飴</div><div class=\"def\">mellitus pastillus, sacchari pastillus.</div>\r\n","<div class=\"hw jl\">飼う</div><div class=\"def\">(=飼育する)alo, pasco, educo;(ペットなどを)habeo.</div>\r\n","<div class=\"hw jl\">飼育</div><div class=\"def\">pastus, pastio, educatio.</div><div class=\"def\">▼<b>～する</b> pasco, educo, alo.</div>\r\n","<div class=\"hw jl\">飽きる</div><div class=\"def\">▼<b>飽きている</b> taedet(<i>impers</i>).</div><div class=\"def\">▼<b>飽きあきした</b> satiatus.</div><div class=\"ex2\">もう同じことを聞き飽きている<span class=\"ext\">taedet jam audire eadem.</span></div>\r\n","<div class=\"hw jl\">飾る</div><div class=\"def\">orno, exorno, decoro, excolo.</div><div class=\"def\">⇒<a href=\"entry://装飾\">装飾</a>.</div>\r\n","<div class=\"hw jl\">養う</div><div class=\"def\">(=扶養する)alo.</div><div class=\"def\">⇒<a href=\"entry://飼育\">飼育</a>,<a href=\"entry://教育\">教育</a>.</div>\r\n","<div class=\"hw jl\">養成</div><div class=\"def\">▼<b>～する</b>(=教育や訓練で形成する)informo, formo, instituo, exerceo.</div>\r\n","<div class=\"hw jl\">養育</div><div class=\"def\">nutricatio, nutricatus, cultus.</div><div class=\"def\">▼<b>～者</b> nutritor, nutricius;(=乳母)nutrix, nutricia.</div><div class=\"def\">▼<b>～する</b> nutrio, nutrico, nutricor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://教育\">教育</a>.</div>\r\n","<div class=\"hw jl\">餌</div><div class=\"def\">esca, cibus;(家畜の)pabulum, pastus.</div>\r\n","<div class=\"hw jl\">饒舌</div><div class=\"def\">loquacitas.</div><div class=\"def\">▼<b>～な</b> loquax.</div><div class=\"def\">▼<b>～に</b> loquaciter.</div>\r\n","<div class=\"hw jl\">首</div><div class=\"def\">collum, cervix.</div>\r\n","<div class=\"hw jl\">首尾一貫</div><div class=\"def\">constantia.</div>\r\n","<div class=\"hw jl\">首相</div><div class=\"def\">administrorum princeps [praeses], minister primarius, primus minister.</div><div class=\"ex2\">(ドイツの)連邦共和国～<span class=\"ext\">cancellarius foederalis.</span></div><div class=\"def\">⇒<a href=\"entry://大臣\">大臣</a>.</div>\r\n","<div class=\"hw jl\">首輪</div><div class=\"def\">collare, collarium.</div>\r\n","<div class=\"hw jl\">首都</div><div class=\"def\">caput.</div>\r\n","<div class=\"hw jl\">首飾り</div><div class=\"def\">monile, torquis, torques.</div>\r\n","<div class=\"hw jl\">香ばしい</div><div class=\"def\">bene olens.</div><div class=\"def\">⇒<a href=\"entry://匂い\">匂い</a>.</div>\r\n","<div class=\"hw jl\">香り</div><div class=\"def\">odor.</div><div class=\"def\">▼<b>～のある</b> odoratus, odorus.</div><div class=\"def\">▼<b>良い～がする</b> bene oleo.</div>\r\n","<div class=\"hw jl\">香料</div><div class=\"def\">odor, odoramentum, odoramen, aroma.</div>\r\n","<div class=\"hw jl\">香水</div><div class=\"def\">unguentum, odoratus liquor.</div><div class=\"def\">▼<b>～石鹸</b> odoratus sapo.</div>\r\n","<div class=\"hw jl\">香辛料</div><div class=\"def\">condimentum.</div><div class=\"def\">▼<b>～を入れる</b> condio.</div>\r\n","<div class=\"hw jl\">馬</div><div class=\"def\">equus;(雌の)equa.</div><div class=\"def\">▼<b>～の</b> equinus.</div>\r\n","<div class=\"hw jl\">馬鹿</div><div class=\"def\">(=愚かな人)stultus(<i>m</i>), stupidus(<i>m</i>), fatuus(<i>m</i>).</div><div class=\"def\">▼<b>～である</b> desipio.</div>\r\n","<div class=\"hw jl\">馴れる</div><div class=\"def\">(動物が)mansuesco, mansuefio, mitesco, mitigor(<i>pass</i>), ad homines assuesco.</div><div class=\"def\">▼<b>馴らす</b> mansuefacio.</div><div class=\"def\">▼<b>馴れていること</b> mansuetudo.</div><div class=\"def\">▼<b>馴れている</b> mansuetus, mansues.</div>\r\n","<div class=\"hw jl\">駅</div><div class=\"def\">(鉄道の)statio ferriviae [ferriviaria].</div><div class=\"def\">⇒<a href=\"entry://鉄道\">鉄道</a>.</div>\r\n","<div class=\"hw jl\">駆けつける</div><div class=\"def\">accurro.</div><div class=\"def\">⇒<a href=\"entry://急ぐ\">急ぐ</a>.</div>\r\n","<div class=\"hw jl\">駐車</div><div class=\"def\">▼<b>～する</b> autocinetum statuo, vehiculum in statione sisto.</div><div class=\"def\">▼<b>～場</b> area stativa, autocinetorum [vehiculorum, autovehiculorum] statio, temporaneum vehiculorum receptaculum.</div><div class=\"def\">⇒<a href=\"entry://車庫\">車庫</a>.</div>\r\n","<div class=\"hw jl\">騎兵</div><div class=\"def\">eques.</div><div class=\"def\">▼<b>～(隊)</b> equitatus, equestres copiae(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://歩兵\">歩兵</a>.</div>\r\n","<div class=\"hw jl\">騎士</div><div class=\"def\">eques.</div><div class=\"def\">▼(集合的に)<b>～たち, ～階級</b> equitatus.</div><div class=\"def\">▼<b>～の</b> equester.</div>\r\n","<div class=\"hw jl\">騎手</div><div class=\"def\">eques.</div><div class=\"def\">▼<b>～の</b> equester.</div>\r\n","<div class=\"hw jl\">騒々しい</div><div class=\"def\">strepens, clamosus.</div>\r\n","<div class=\"hw jl\">騒がしい</div><div class=\"def\">turbatus.</div>\r\n","<div class=\"hw jl\">騒ぎ</div><div class=\"def\">agitatio, turba, tumultus.</div><div class=\"def\">⇒<a href=\"entry://騒動\">騒動</a>,<a href=\"entry://混乱\">混乱</a>.</div>\r\n","<div class=\"hw jl\">騒ぐ</div><div class=\"def\">tumultuor(<i>dep</i>);(=わいわい騒ぐ)strepo.</div>\r\n","<div class=\"hw jl\">騒動</div><div class=\"def\">tumultus, tumultuatio, turba, turbatio.</div><div class=\"def\">▼<b>～を起こす</b> tumultuor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://混乱\">混乱</a>.</div>\r\n","<div class=\"hw jl\">騒音</div><div class=\"def\">strepitus, sonitus.</div><div class=\"ex2\">～を響かせる<span class=\"ext\">strepo.</span></div><div class=\"def\">⇒<a href=\"entry://騒動\">騒動</a>.</div>\r\n","<div class=\"hw jl\">驚かす</div><div class=\"def\">terrifico, pavefacio, terreo, perterreo.</div>\r\n","<div class=\"hw jl\">驚く</div><div class=\"def\">(=あきれる, 驚嘆する, 不思議がる)miror(<i>dep</i>), admiror;(=見て驚く)stupeo;(=怖がる)terreor(<i>pass</i>), paveo.</div><div class=\"def\">▼<b>～べき</b> mirus, admirabilis.</div><div class=\"def\">▼<b>驚き</b>(=驚嘆の念)admiratio.</div>\r\n","<div class=\"hw jl\">骨</div><div class=\"def\">os.</div>\r\n","<div class=\"hw jl\">骨折</div><div class=\"def\">(ossis)fractura.</div><div class=\"def\">⇒<a href=\"entry://折る\">折る</a>.</div>\r\n","<div class=\"hw jl\">骨格</div><div class=\"def\">(corpori subjecta)ossa(<i>pl</i>), ossium positus figuraque, compages.</div><div class=\"def\">⇒<a href=\"entry://骨\">骨</a>.</div>\r\n","<div class=\"hw jl\">骨董</div><div class=\"def\">(品)res antiquo opere et summo artificio facta.</div>\r\n","<div class=\"hw jl\">骨髄</div><div class=\"def\">medulla.</div>\r\n","<div class=\"hw jl\">高い</div><div class=\"def\">(空間的に)altus, procerus, celsus, excelsus, editus, sublimis;(値段が)(=高価な)carus, pretiosus;(声が)(=かん高い)acutus.</div><div class=\"def\">▼(空間的に)<b> 高く</b> alte.</div><div class=\"def\">▼<b>高さ</b> altitudo, proceritas.</div>\r\n","<div class=\"hw jl\">高価</div><div class=\"def\">▼<b>～な</b> carus, pretiosus, sumptuosus.</div><div class=\"def\">⇒<a href=\"entry://ぜいたく\">ぜいたく</a>.</div>\r\n","<div class=\"hw jl\">高利</div><div class=\"def\">magnum [grave] faenus.</div><div class=\"ex2\">～で融資する<span class=\"ext\">pecuniam occupo grandi faenore.</span></div><div class=\"def\">⇒<a href=\"entry://利子\">利子</a>.</div>\r\n","<div class=\"hw jl\">高原</div><div class=\"def\">planities, campus editus.</div>\r\n","<div class=\"hw jl\">高圧</div><div class=\"def\">alta tensura [tensio].</div>\r\n","<div class=\"hw jl\">高層</div><div class=\"def\">▼<b>～の</b> supereditus.</div><div class=\"def\">▼<b>～ビル</b> superedita aedes.</div>\r\n","<div class=\"hw jl\">高度</div><div class=\"def\">⇒<a href=\"entry://高い\">高い</a>.</div>\r\n","<div class=\"hw jl\">高所</div><div class=\"def\">altitudo, locus editus, loca superiora [editiora](<i>pl</i>).</div><div class=\"def\">▼<b>～から</b> ex loco superiore.</div><div class=\"def\">⇒<a href=\"entry://丘\">丘</a>,<a href=\"entry://山\">山</a>,<a href=\"entry://高原\">高原</a>.</div>\r\n","<div class=\"hw jl\">高校</div><div class=\"def\">lyceum, gymnasium.</div><div class=\"def\">⇒<a href=\"entry://学校\">学校</a>.</div>\r\n","<div class=\"hw jl\">高貴</div><div class=\"def\">nobilitas.</div><div class=\"def\">▼<b>～な</b> noblilis, generosus, honestus, amplus.</div><div class=\"def\">⇒<a href=\"entry://気高い\">気高い</a>.</div>\r\n","<div class=\"hw jl\">高齢</div><div class=\"def\">▼<b>～の</b> aetate provectus.</div><div class=\"def\">⇒<a href=\"entry://老いる\">老いる</a>.</div>\r\n","<div class=\"hw jl\">髪</div><div class=\"def\">capillus, crinis.</div><div class=\"def\">▼<b>～型</b> genus capillorum ornatus.</div><div class=\"def\">▼<b>～の, ～に関する</b> crinalis.</div><div class=\"def\">▼<b>～の生えた, ～におおわれた</b> crinitus.</div>\r\n","<div class=\"hw jl\">髭</div><div class=\"def\">(あごと頬の)barba;(唇の上の)barba [capilli] labri superioris.</div><div class=\"ex2\">～は哲学者をつくらない<span class=\"ext\">barba non facit philosophum.</span></div>\r\n","<div class=\"hw jl\">鬱病</div><div class=\"def\">melancholia.</div><div class=\"def\">▼<b>～の</b> melancholicus.</div>\r\n","<div class=\"hw jl\">鬱蒼とした</div><div class=\"def\">umbrosus.</div>\r\n","<div class=\"hw jl\">魂</div><div class=\"def\">animus, anima;(死者の)manes(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://精神\">精神</a>.</div>\r\n","<div class=\"hw jl\">魅力</div><div class=\"def\">(=優美)lepor, lepos, suavitas, jucunditas, venustas, dulcedo.</div><div class=\"def\">▼<b>～的な</b>(=優美な)lepidus, suavis, jucundus, venustus, dulcis.</div><div class=\"def\">⇒<a href=\"entry://美しい\">美しい</a>.</div>\r\n","<div class=\"hw jl\">魔女</div><div class=\"def\">(=女妖術師, 女魔術師)venefica, cantatrix, praecantrix, maga.</div><div class=\"def\">⇒<a href=\"entry://魔法\">魔法</a>.</div>\r\n","<div class=\"hw jl\">魔法</div><div class=\"def\">magice, magia, magicae artes(<i>pl</i>).</div><div class=\"def\">▼<b>～使い</b> maga(<i>f</i>), magus(<i>f</i>).</div><div class=\"def\">▼<b>～の</b> magicus, magus.</div><div class=\"def\">▼(呪文によって)<b> ～をかける</b> incanto.</div>\r\n","<div class=\"hw jl\">魚</div><div class=\"def\">piscis.</div><div class=\"def\">▼<b>～屋</b> piscatoria taberna.</div><div class=\"def\">▼<b>～がたくさんいる</b> piscosus.</div><div class=\"def\">▼<b>～を釣る</b> piscor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">鮭</div><div class=\"def\">salmo.</div>\r\n","<div class=\"hw jl\">鮮やかな</div><div class=\"def\">(色が)vegetus.</div>\r\n","<div class=\"hw jl\">鯖</div><div class=\"def\">scomber.</div>\r\n","<div class=\"hw jl\">鯨</div><div class=\"def\">balaena.</div>\r\n","<div class=\"hw jl\">鰯</div><div class=\"def\">sarda.</div>\r\n","<div class=\"hw jl\">鱗</div><div class=\"def\">squama.</div><div class=\"ex2\">目から～<span class=\"ext\">caligo discussa est.</span></div>\r\n","<div class=\"hw jl\">鳥</div><div class=\"def\">avis, volucris.</div><div class=\"def\">▼<b>小～</b> passer, avicula.</div>\r\n","<div class=\"hw jl\">鳩</div><div class=\"def\">columba;(雄の)columbus(<i>m</i>).</div>\r\n","<div class=\"hw jl\">鳴き声</div><div class=\"def\">(動物の)vox, clamor;(象の)stridor, barritus;(山羊の)vagitus;(鵞鳥や鷲の)clangor;(鶏の)cantus;(鳩・孔雀・蛙の)querela.</div><div class=\"def\">⇒<a href=\"entry://叫ぶ\">叫ぶ</a>,<a href=\"entry://ほえる\">ほえる</a>.</div>\r\n","<div class=\"hw jl\">鳴く</div><div class=\"def\">(動物が)vocem edo, clamo;(蛙が)coaxo;(烏が)croccio;(鴨が)tetrinnio;(雄鶏が)canto.</div><div class=\"def\">⇒<a href=\"entry://ほえる\">ほえる</a>.</div>\r\n","<div class=\"hw jl\">鳴り響く</div><div class=\"def\"><span class=\"pos3\">[形]</span> sonorus.</div><div class=\"def\">⇒<a href=\"entry://音\">音</a>.</div>\r\n","<div class=\"hw jl\">鳴る</div><div class=\"def\">sono, tinnio.</div><div class=\"def\">⇒<a href=\"entry://音\">音</a>.</div>\r\n","<div class=\"hw jl\">鴨</div><div class=\"def\">anas;(子鴨)anaticula.</div>\r\n","<div class=\"hw jl\">鶏</div><div class=\"def\">(雌の)gallina;(雄の)gallus(gallinaceus), mas gallinaceus;(若い)pullus(gallinaceus), gallinula.</div><div class=\"def\">▼<b>～小屋</b> gallinarium.</div><div class=\"def\">▼<b>～の</b> gallinaceus.</div><div class=\"ex2\">～の卵<span class=\"ext\">ovum gallinaceum.</span></div>\r\n","<div class=\"hw jl\">鶴</div><div class=\"def\">grus.</div>\r\n","<div class=\"hw jl\">麦</div><div class=\"def\">(=小麦)triticum.</div><div class=\"def\">▼<b>～粒</b> granum tritici.</div><div class=\"def\">▼<b>～畑</b> frumentarius ager.</div><div class=\"def\">▼<b>～わら</b> triticea pallea.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">小麦粉<span class=\"ext\">farina.</span></div><div class=\"cf\">大麦<span class=\"ext\">hordeum.</span></div><div class=\"cf\">大麦パン<span class=\"ext\">hordeaceus panis.</span></div>\r\n","<div class=\"hw jl\">麻</div><div class=\"def\">(植物)cannabis;(布, 糸)linum.</div>\r\n","<div class=\"hw jl\">麻痺</div><div class=\"def\">torpor, stupor, nervorum resolutio, paralysis, membrorum debilitas.</div><div class=\"def\">▼<b>感覚の～</b> sensūs stupor.</div><div class=\"def\">▼<b>～させる</b> resolvo, debilito.</div><div class=\"def\">▼<b>～する</b> torpeo.</div><div class=\"def\">▼<b>～している</b> torpeo.</div><div class=\"def\">▼<b>～した</b> resolutus, debilis, torpens, torpidus, obtusus.</div>\r\n","<div class=\"hw jl\">麻薬</div><div class=\"def\">medicamentum stupefactivum.</div><div class=\"def\">▼<b>～中毒</b> toxicomania, medicamentis stupefactivis obnoxietas.</div><div class=\"def\">▼<b>～中毒にかかっている</b> medicamentis stupefactivis assuetus.</div>\r\n","<div class=\"hw jl\">麻酔</div><div class=\"def\">anaesthesia, doloris amotio [privatio], sentiendi facultatis privatio.</div><div class=\"def\">▼<b>～薬</b> anaesthetica(<i>pl</i>).</div><div class=\"def\">▼<b>～をかける</b> doloris sensum medicamentis obtundo, facultatem sentiendi doloris aufero.</div>\r\n","<div class=\"hw jl\">黄</div><div class=\"def\">▼<b>～色の</b> flavus.</div><div class=\"def\">▼<b>赤～色の</b> fulvus.</div><div class=\"def\">⇒<a href=\"entry://サフラン\">サフラン</a>.</div>\r\n","<div class=\"hw jl\">黒</div><div class=\"def\">▼<b>～い</b> ater, niger.</div><div class=\"def\">▼<b>～(色)</b> color ater, color niger.</div>\r\n","<div class=\"hw jl\">黒人</div><div class=\"def\">homo nigricolor, cives nigricolores(<i>pl</i>), nigritae(<i>pl</i>), Aethiops.</div><div class=\"def\">⇒<a href=\"entry://黒\">黒</a>.</div>\r\n","<div class=\"hw jl\">黒板</div><div class=\"def\">(=書き板)tabula, tabella.</div>\r\n","<div class=\"hw jl\">黙る</div><div class=\"def\">(=黙っている)taceo, sileo, linguam comprimo.</div><div class=\"def\">▼<b>黙って</b> silentio, tacite, per tacitum.</div><div class=\"def\">▼<b>黙れ</b> os opprime.</div>\r\n","<div class=\"hw jl\">黙劇</div><div class=\"def\">(=無言劇)mimus.</div><div class=\"def\">▼<b>～役者</b> mimus.</div><div class=\"def\">▼<b>～の</b> mimicus.</div><div class=\"def\">⇒<a href=\"entry://演劇\">演劇</a>.</div>\r\n","<div class=\"hw jl\">鼓動</div><div class=\"def\">(心臓の)cordis palpitatio.</div><div class=\"def\">⇒<a href=\"entry://脈\">脈</a>.</div>\r\n","<div class=\"hw jl\">鼓笛隊</div><div class=\"def\">tympanistarum et tibicinum grex.</div>\r\n","<div class=\"hw jl\">鼓舞</div><div class=\"def\">▼<b>～する</b> adjuvo, confirmo.</div><div class=\"def\">⇒<a href=\"entry://励ます\">励ます</a>.</div>\r\n","<div class=\"hw jl\">鼻</div><div class=\"def\">nasus.</div><div class=\"def\">▼<b>～の穴</b> naris.</div><div class=\"def\">▼<b>～をかむ</b> se emungere(← emungo).</div>\r\n","<div class=\"hw jl\">鼻血</div><div class=\"def\">profluvium e naribus.</div>\r\n"]);
